('original:science--earth-space-science--volcanoes:science--earth-space-science--volcanoes--15',1,'{"question":"Why do volcano scientists combine deformation, gas, and seismic measurements?","choices":["One measurement gives an exact eruption time in every case","All indicators measure identical processes","These data eliminate every uncertainty","Multiple indicators can reveal changes in the volcanic system"],"answer":3,"explanation":""}'::jsonb,'e48214e48bb6021473f244df6824be8e','official',NULL,NULL,'Volcanoes'),
