('original:science--earth-space-science--volcanoes:science--earth-space-science--volcanoes--17',1,'{"question":"Rain mixes with loose ash on a volcano''s slopes and flows downhill. Which hazard best fits?","choices":["Tsunami caused only by wind","Ice wedging","Seafloor spreading","Lahar"],"answer":3,"explanation":""}'::jsonb,'2b48a0a04f6154fc0c16de6c8ac53662','official',NULL,NULL,'Volcanoes'),
('original:science--earth-space-science--volcanoes:science--earth-space-science--volcanoes--18',1,'{"question":"A gas-rich, highly viscous magma rises toward lower pressure. Which possibility deserves attention?","choices":["A guarantee that no eruption can occur","An explosive eruption if gas cannot escape readily","Permanent disappearance of all gases","Conversion of magma directly into seawater"],"answer":1,"explanation":""}'::jsonb,'5a70f86384b3346e6c72b1fd333b07cf','official',NULL,NULL,'Volcanoes'),
('original:science--earth-space-science--volcanoes:science--earth-space-science--volcanoes--19',1,'{"question":"A chain of hotspot islands becomes older away from its active end. What does this pattern suggest?","choices":["All islands formed simultaneously","The ocean has no tectonic motion","A plate moved over a relatively persistent magma source","Older islands must contain no volcanic rock"],"answer":2,"explanation":""}'::jsonb,'7fe09929337ab1a98f46ababf3dc3dd6','official',NULL,NULL,'Volcanoes'),
('original:science--earth-space-science--volcanoes:science--earth-space-science--volcanoes--20',1,'{"question":"A hazard map shows past lava paths and low-lying channels. What is an appropriate use?","choices":["Determining the exact eruption date","Guaranteeing that unshaded areas have no hazards","Replacing every monitoring instrument","Assessing likely affected areas while recognizing uncertainty"],"answer":3,"explanation":""}'::jsonb,'10e7cd3899ac33d4ea9659e630046cf0','official',NULL,NULL,'Volcanoes'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--1',1,'{"question":"What does relative dating determine?","choices":["The exact numerical age of every rock","The time taken to erode an entire landscape","Whether an event is older or younger than another","The temperature at which a fossil formed"],"answer":2,"explanation":""}'::jsonb,'61971a0eeb24607ef72075e6d9ab82e4','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--2',1,'{"question":"In an undisturbed sequence of sedimentary layers, where are the oldest layers normally found?","choices":["At the top","At the bottom","Only in the middle","Only on the western side"],"answer":1,"explanation":""}'::jsonb,'720245a2a5c28b8508d82c4a7ed35e55','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--3',1,'{"question":"What is a trace fossil?","choices":["A mineral replacement of an organism''s body tissue","A modern organism collected for comparison","A fossil shell preserved as an original body part","Preserved evidence of an organism''s activity"],"answer":3,"explanation":""}'::jsonb,'9eb7f30f086d364432e86fe0e67a0f12','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--4',1,'{"question":"What is an unconformity in a rock sequence?","choices":["A layer showing continuous deposition without a gap","A boundary between minerals within one crystal","A surface that always has younger rocks below older rocks","A surface representing missing geologic time"],"answer":3,"explanation":""}'::jsonb,'acc81681005f37afd6e38fb877186844','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--5',1,'{"question":"What makes an index fossil useful for correlating rock layers?","choices":["Occurrence at only one site over all of Earth''s history","Wide distribution and a relatively short geologic time range","A large body size regardless of age","An absence from sedimentary rocks"],"answer":1,"explanation":""}'::jsonb,'099a97b1ca02002dfa854e9314b7a2a2','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--6',1,'{"question":"What process underlies radiometric dating?","choices":["A constant rate of sediment deposition in every setting","The gradual darkening of rock with age","Predictable radioactive decay of isotopes","The rate at which every fossil increases in size"],"answer":2,"explanation":""}'::jsonb,'66dbf20f1e6d0e1c84d2d68d9aa36f9e','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--7',1,'{"question":"Which geologic era includes most of the time non-avian dinosaurs lived?","choices":["Mesozoic","Cenozoic","Paleozoic","Archean"],"answer":0,"explanation":""}'::jsonb,'fef35a687aefa32699759dd7c73f98ae','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--8',1,'{"question":"Why is the fossil record incomplete?","choices":["All organisms leave equally complete fossils","Preservation requires conditions that do not occur for every organism","Only modern organisms can be fossilized","Sedimentary rocks never preserve biological remains"],"answer":1,"explanation":""}'::jsonb,'4024c278908f26584805a6dab6087d41','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--9',1,'{"question":"Why are hard body parts often preserved more readily than soft tissues?","choices":["They resist decay and destruction better under many conditions","Soft tissues cannot ever be preserved","Hard parts always fossilize without burial","Soft tissues decay only in modern organisms"],"answer":0,"explanation":""}'::jsonb,'302fae3e5c4e638273ade31973999754','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--10',1,'{"question":"How can a volcanic ash layer help estimate the age of fossils in nearby layers?","choices":["Ash automatically gives every nearby fossil the same exact age","Ash minerals date the living organism directly without context","Suitable ash minerals can be radiometrically dated","Ash thickness alone gives an exact age"],"answer":2,"explanation":""}'::jsonb,'a91fd52f8beaedb67b9494222cddd61b','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--11',1,'{"question":"Why is carbon-14 dating unsuitable for dinosaur fossils tens of millions of years old?","choices":["Carbon-14 dating works only for inorganic crystals","Carbon-14 has too long a half-life for ancient material","The organism''s size determines the isotope''s half-life","Too little original carbon-14 remains after so much time"],"answer":3,"explanation":""}'::jsonb,'6360b0959965a0415a709c2892d25f9c','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--12',1,'{"question":"What do marine fossils in rocks far inland suggest about the rock''s environment of formation?","choices":["The area has always had its present climate and elevation","The area was once covered by water supporting marine life","Marine fossils cannot be preserved outside today''s oceans","All marine fossils were transported by modern rivers"],"answer":1,"explanation":""}'::jsonb,'ee5d538d398625e376c9836972e01478','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--13',1,'{"question":"Why does a fault cutting through several rock layers indicate the fault is younger than those layers?","choices":["Faults form before any rock exists","Older layers cannot be broken","The fault''s color determines its age","The layers had to exist before they could be cut"],"answer":3,"explanation":""}'::jsonb,'7044ff42e569869c162e0816bb513809','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--14',1,'{"question":"How does an intrusion''s age compare with the rock it cuts?","choices":["The intrusion is younger","The intrusion is always older","Both must have identical ages","Their ages depend only on their thickness"],"answer":0,"explanation":""}'::jsonb,'dbcf40eef66801cf6a11da757985cd6d','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--15',1,'{"question":"Why are fossils and radiometric dates used together?","choices":["Fossils alone provide exact calendar years","Radiometric methods directly date every fossil equally well","They provide complementary evidence for correlating and dating events","Both methods provide only the rock''s mineral composition"],"answer":2,"explanation":""}'::jsonb,'329c2694dc02a168ac53b0786ef2e003','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--16',1,'{"question":"Layer A lies below B, and B below C, with no disturbance. Which order is oldest to youngest?","choices":["C, B, A","B, A, C","A, B, C","A, C, B"],"answer":2,"explanation":""}'::jsonb,'0d80b41c69d7cfa7e76a8867d68a1aaa','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--17',1,'{"question":"A fossil-bearing layer lies between ash layers dated 12 and 10 million years old. What age range is consistent with the fossil layer?","choices":["Between 10 and 12 million years","Between 1 and 2 million years","Older than 20 million years","Younger than 1 million years"],"answer":0,"explanation":""}'::jsonb,'1f1af0a96e0db1d000a3e16d7302fc5c','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--18',1,'{"question":"Half of a radioactive parent isotope remains after one half-life. How much remains after two half-lives?","choices":["One-half","Three-fourths","None","One-fourth"],"answer":3,"explanation":""}'::jsonb,'45e6f10302285b5b184acdcef633c04e','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--19',1,'{"question":"Two distant rock layers contain the same suitable index fossil. What does this support?","choices":["They must have identical thickness","They formed during a similar geologic time interval","They formed in the same exact location","They contain equal amounts of every mineral"],"answer":1,"explanation":""}'::jsonb,'6c628a44f0bad3066b91c5a73a712796','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--geologic-time-and-fossils:science--earth-space-science--geologic-time-and-fossils--20',1,'{"question":"An erosion surface separates two sedimentary units. What should a geologist consider?","choices":["Some time may be missing from the local rock record","Deposition was necessarily continuous","The upper unit must be older","The surface proves no organisms existed then"],"answer":0,"explanation":""}'::jsonb,'bf8899bfe8c047810788ea95481f011e','official',NULL,NULL,'Geologic Time and Fossils'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--1',1,'{"question":"Which gas makes up the largest fraction of Earth''s dry atmosphere?","choices":["Oxygen","Nitrogen","Carbon dioxide","Argon"],"answer":1,"explanation":""}'::jsonb,'d41c2e656b938425cc337f91f1673627','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--2',1,'{"question":"What is atmospheric pressure primarily caused by?","choices":["The temperature of air alone, regardless of its amount","Only the pressure exerted by falling rain","The weight of overlying air","The mass of water vapor without the other gases"],"answer":2,"explanation":""}'::jsonb,'40f9a14e57b2f15a875775b659a23222','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--3',1,'{"question":"Which gas makes up about one-fifth of Earth''s dry atmosphere?","choices":["Oxygen","Nitrogen","Carbon dioxide","Argon"],"answer":0,"explanation":""}'::jsonb,'8e4957c2258b101e8828e45a0e75ecc1','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--4',1,'{"question":"In which atmospheric layer does most weather occur?","choices":["Troposphere","Stratosphere","Mesosphere","Thermosphere"],"answer":0,"explanation":""}'::jsonb,'9f83820db8e717e6565b5d67863e7533','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--5',1,'{"question":"Which atmospheric layer contains most of the ozone layer?","choices":["Troposphere","Mesosphere","Stratosphere","Exosphere"],"answer":2,"explanation":""}'::jsonb,'a3c05523418fee5dbb51c1ecda0b3297','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--6',1,'{"question":"What is a pressure gradient?","choices":["A change in temperature over distance only","A change in pressure over distance","The pressure recorded at one point with no comparison","The humidity recorded over one hour"],"answer":1,"explanation":""}'::jsonb,'d93e674f9d97e5b8239cc03e650955cc','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--7',1,'{"question":"What does humidity describe?","choices":["Only liquid droplets suspended in clouds","Only the pressure of the atmosphere","The concentration of airborne dust","Water vapor in the air"],"answer":3,"explanation":""}'::jsonb,'dc598e9df60829efb640db5b5b589e72','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--8',1,'{"question":"Why does air pressure generally decrease with altitude?","choices":["The mass of each air molecule decreases with elevation","Gravity becomes stronger enough to remove pressure","There is less overlying air","High-altitude air contains no molecules"],"answer":2,"explanation":""}'::jsonb,'1ba8cae2b2e551c9476f2d3d7d7f7f7e','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--9',1,'{"question":"Why can warmed air rise in surrounding cooler air?","choices":["Warming increases density under the same outside pressure","Warm air rises because its particles lose all mass","Temperature differences have no effect on air density","It expands and becomes less dense under suitable conditions"],"answer":3,"explanation":""}'::jsonb,'508064e12cb41b9079076bbe6a91c0db','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--10',1,'{"question":"What drives horizontal air motion from pressure differences?","choices":["The transfer of heat without a pressure difference","A pressure-gradient force","Only the attraction of air toward mountains","The weight of clouds as a separate horizontal force"],"answer":1,"explanation":""}'::jsonb,'a1ed150fd3f41b5a7f05fb75fe8e74f3','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--11',1,'{"question":"How does Earth''s rotation affect large-scale moving air?","choices":["It deflects its path through the Coriolis effect","It removes all pressure gradients","It forces all winds to travel vertically","It makes global air motion independent of pressure differences"],"answer":0,"explanation":""}'::jsonb,'b66a671c0cbbd097929747b830534c6c','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--12',1,'{"question":"Why can rising moist air form clouds?","choices":["Water vapor remains gaseous at every temperature","Expansion warms air enough to form liquid droplets","Expansion cools the air, allowing water vapor to condense","Rising air always loses all its water vapor"],"answer":2,"explanation":""}'::jsonb,'83b066882662a058a538e63c9f30bebb','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--13',1,'{"question":"Why do high-pressure systems often bring clearer weather?","choices":["Descending air tends to warm and inhibit cloud formation","High pressure guarantees heavy rain everywhere","Descending air always cools by expansion","Clouds can form only when pressure is high"],"answer":0,"explanation":""}'::jsonb,'49ebd7fada82bafb3ebb36f50adef007','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--14',1,'{"question":"Why is the ozone layer important?","choices":["It blocks all visible sunlight from the surface","It supplies most atmospheric oxygen through photosynthesis","It determines all surface wind directions","It absorbs much harmful ultraviolet radiation"],"answer":3,"explanation":""}'::jsonb,'5cac0d452965768e7aa2b4e3c312704e','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--15',1,'{"question":"Why does air exert pressure on all sides of an object?","choices":["Pressure acts only downward on exposed surfaces","Moving gas molecules collide with surfaces in many directions","Air molecules move in only one direction","Pressure exists only in sealed containers"],"answer":1,"explanation":""}'::jsonb,'3c34bf02c4e4133ab92d0069315a3a45','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--16',1,'{"question":"A climber measures lower pressure on a mountain than at sea level. Which explanation best fits?","choices":["The mountain creates new gas molecules","Less air lies above the higher location","The sea-level air has no weight","Higher altitude always means stronger gravity"],"answer":1,"explanation":""}'::jsonb,'251aa7254ed62178d78e93303383902a','official',NULL,NULL,'Atmosphere and Air Pressure')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--17',1,'{"question":"Two nearby areas differ in pressure. Ignoring rotation and friction, which way is air accelerated?","choices":["From lower toward higher pressure","Parallel to equal-pressure lines with no acceleration","Only toward warmer ground regardless of pressure","From higher toward lower pressure"],"answer":3,"explanation":""}'::jsonb,'dc7cc149aeb72e87495ca78b09cedbd5','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--18',1,'{"question":"Warm air over land rises while cooler sea air moves inland at the surface. What circulation is described?","choices":["A daytime sea breeze","A nighttime land breeze","A jet stream above the poles","An ocean tide"],"answer":0,"explanation":""}'::jsonb,'a5860ed0792c16b2d52eeac5a0360282','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--19',1,'{"question":"A sealed flexible balloon expands as outside pressure decreases, with temperature unchanged. What explains the expansion?","choices":["Its gas mass must increase immediately","Its temperature must rise despite the stated condition","The gas can occupy more volume under lower external pressure","Its internal pressure can never respond to external pressure"],"answer":2,"explanation":""}'::jsonb,'8708c6ba99994ea84d156b84e4decb16','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--atmosphere-and-air-pressure:science--earth-space-science--atmosphere-and-air-pressure--20',1,'{"question":"Two air samples have the same temperature and volume, but one contains more gas particles. Which generally has greater pressure?","choices":["The sample with fewer particles","Both must have zero pressure","The darker-colored sample","The sample with more particles"],"answer":3,"explanation":""}'::jsonb,'eae51dfed5506174361b298dc7b59591','official',NULL,NULL,'Atmosphere and Air Pressure'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--1',1,'{"question":"What describes climate rather than weather?","choices":["Long-term patterns and averages of atmospheric conditions","The rainfall during one afternoon","The wind speed at one instant","The temperature on one morning"],"answer":0,"explanation":""}'::jsonb,'d5c42b8b85eca2e8407226cffd937868','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--2',1,'{"question":"What is the natural greenhouse effect?","choices":["Atmospheric gases reflect every form of sunlight back to space","The atmosphere prevents all outgoing radiation","Clouds generate the solar energy reaching Earth","Atmospheric gases absorb and emit infrared radiation, warming the surface and lower atmosphere"],"answer":3,"explanation":""}'::jsonb,'bca5e6530655d003510a45ee9155147d','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--3',1,'{"question":"Which gas is a greenhouse gas?","choices":["Nitrogen","Carbon dioxide","Oxygen","Argon"],"answer":1,"explanation":""}'::jsonb,'f457ce82c6ae6ef9550c2d4476f80326','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--4',1,'{"question":"What is albedo?","choices":["The fraction of radiation a surface absorbs only","The fraction of incoming radiation a surface reflects","The speed at which a surface loses heat by conduction","The total infrared radiation emitted by the atmosphere"],"answer":1,"explanation":""}'::jsonb,'9c1631da9b07f5130f768ed4ac03ab23','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--5',1,'{"question":"What is a climate proxy?","choices":["A forecast of one day''s future weather","A direct reading from every ancient thermometer","A model that changes the measured climate","Indirect evidence of past climate"],"answer":3,"explanation":""}'::jsonb,'e78c5845703dace943d4dde17ee4a42e','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--6',1,'{"question":"Which source can provide evidence of ancient atmospheric composition?","choices":["Air bubbles trapped in ice cores","A modern weather forecast for the same location","The current thickness of one cloud","A single afternoon''s wind-speed reading"],"answer":0,"explanation":""}'::jsonb,'f59be566d972c0756f59427f11ccb7aa','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--7',1,'{"question":"What is climate mitigation?","choices":["Adjusting only to climate effects after they occur","Recording short-term weather without acting on causes","Reducing the causes or magnitude of climate change","Preparing buildings only for impacts that cannot be reduced"],"answer":2,"explanation":""}'::jsonb,'4cc6e29190fd38044e1824ae0591f1f4','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--8',1,'{"question":"Why does burning fossil fuels contribute to recent warming?","choices":["It permanently removes carbon dioxide from the atmosphere","It prevents greenhouse gases from absorbing infrared radiation","It affects temperature only where the fuel is burned","It adds carbon dioxide that changes Earth''s energy balance"],"answer":3,"explanation":""}'::jsonb,'edb9c50725345588334a8de38ffa3d98','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--9',1,'{"question":"Why does one cold day not disprove a long-term warming trend?","choices":["Climate is determined by the most recent temperature alone","A warming trend requires every day to be warmer than all earlier days","Daily weather varies within long-term climate trends","Local temperatures always equal the global average"],"answer":2,"explanation":""}'::jsonb,'56a05e19e5035369cf4a55d4f981ea8f','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--10',1,'{"question":"How can melting reflective ice amplify warming?","choices":["Darker exposed surfaces absorb more solar energy","Darker exposed surfaces reflect more radiation","Less ice necessarily makes Earth emit no infrared radiation","Melting lowers solar absorption regardless of surface reflectivity"],"answer":0,"explanation":""}'::jsonb,'8f660a6eef8c183b7e7af9f0ad25b01f','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--11',1,'{"question":"Why can warming oceans contribute to sea-level rise?","choices":["Warm seawater always occupies less volume","Warmer seawater expands","The water''s mass must increase solely from warming","Ocean temperature has no effect on water volume"],"answer":1,"explanation":""}'::jsonb,'8e29e63c68d0b6797eafc239fdbff725','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--12',1,'{"question":"How does melting land-based ice affect sea level?","choices":["It removes ocean water through freezing","It has the same direct effect as melting floating sea ice","Land ice never exchanges water with the ocean","It adds water to the ocean"],"answer":3,"explanation":""}'::jsonb,'22da8ae2bd26df7772cdfc708eff90f7','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--13',1,'{"question":"Why do scientists use several independent climate measurements?","choices":["One local thermometer fully represents every region","Agreement among different evidence sources strengthens conclusions","Only measurements supporting the initial prediction should be used","Agreement proves that no uncertainty remains"],"answer":1,"explanation":""}'::jsonb,'16d5f8ce79bb6a37f3496d5f1cc88389','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--14',1,'{"question":"What is climate adaptation?","choices":["Reducing greenhouse-gas emissions as its main definition","Measuring the natural greenhouse effect without changing practices","Adjusting systems to reduce harm from climate impacts","Preventing all natural variations in climate"],"answer":2,"explanation":""}'::jsonb,'944b71c66ee5a963b09cf5f984bb1e46','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--15',1,'{"question":"Why are climate projections often given for different emissions scenarios?","choices":["Future human activities affect the magnitude of change","The physical laws are different in each scenario","All future emissions pathways have the same outcome","A scenario is a guarantee of one exact future temperature"],"answer":0,"explanation":""}'::jsonb,'d4496703d7a5cce26a72a2c75f8f3e8e','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--16',1,'{"question":"A city''s yearly mean temperatures fluctuate but rise over 40 years. Which interpretation is reasonable?","choices":["Year-to-year variability can coexist with long-term warming","Every year must be warmer than the one before it","The coldest year invalidates the entire trend","Annual variability means no averages can be calculated"],"answer":0,"explanation":""}'::jsonb,'9e1da7aab0b8a63a2539274e1a2a1eb8','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--17',1,'{"question":"Which action is an example of adaptation?","choices":["Reducing fossil-fuel use to lower emissions","Capturing carbon dioxide before release","Improving drainage to cope with heavier rainfall","Replacing coal generation to reduce emissions"],"answer":2,"explanation":""}'::jsonb,'5bf52ce127c847f63d646a043098ae99','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--18',1,'{"question":"Which observation is stronger evidence of global warming than one hot day?","choices":["A high temperature in one classroom","A sustained rise in global average temperature across decades","One afternoon of low humidity","A single local thunderstorm"],"answer":1,"explanation":""}'::jsonb,'bf149ae3aecf26012a4e14047c68423f','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--19',1,'{"question":"A warming surface melts snow, lowering reflectivity and increasing heat absorption. What kind of feedback is described?","choices":["Negative feedback that opposes the initial warming","No feedback because snow is involved","Feedback that creates energy from nothing","Positive feedback that amplifies the initial warming"],"answer":3,"explanation":""}'::jsonb,'b5307b9ef43e8b1f118e870d1b8f3731','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--climate-and-climate-change:science--earth-space-science--climate-and-climate-change--20',1,'{"question":"A projection gives a range rather than one exact temperature. What is the appropriate interpretation?","choices":["It proves all temperatures are equally likely","It means measurements have no value","It reflects uncertainty and differing possible conditions","It guarantees the lowest value will occur"],"answer":2,"explanation":""}'::jsonb,'789902d341c732e5703600857352ac85','official',NULL,NULL,'Climate and Climate Change'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--1',1,'{"question":"What is an ocean current?","choices":["Only the vertical rise and fall of sea level","Only a wave''s surface shape moving without a water-flow pattern","The amount of salt dissolved in seawater","A directed movement of seawater"],"answer":3,"explanation":""}'::jsonb,'d4ea7a37aa357620194f1eee24ab0299','official',NULL,NULL,'Ocean Currents and Tides'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--2',1,'{"question":"What causes ocean tides primarily?","choices":["Gravitational interactions involving Earth, Moon, and Sun","Only wind blowing across coastal water","Only changes in atmospheric pressure","Only daily heating of the ocean surface"],"answer":0,"explanation":""}'::jsonb,'6ce2c34a2e1883bd2b2f60e083823a4f','official',NULL,NULL,'Ocean Currents and Tides'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--3',1,'{"question":"What is tidal range?","choices":["The distance between two continents","The speed of a breaking wave","The vertical difference between high and low tide","The salt concentration at high tide"],"answer":2,"explanation":""}'::jsonb,'668eccc9a209785be25b994212e24a11','official',NULL,NULL,'Ocean Currents and Tides'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--4',1,'{"question":"What are spring tides?","choices":["Tides occurring only during the spring season","Tides with the smallest ranges at quarter Moon","Tides with relatively large ranges when Sun, Earth, and Moon align","Tides produced only by changing wind"],"answer":2,"explanation":""}'::jsonb,'567f7fd55bd1eff9718f0058e3daf6fa','official',NULL,NULL,'Ocean Currents and Tides'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--5',1,'{"question":"What are neap tides?","choices":["Tides with relatively small ranges near quarter-moon phases","Tides with greatest ranges near new and full Moon","Tides occurring only during the winter season","Tides caused only by a change in ocean temperature"],"answer":0,"explanation":""}'::jsonb,'e14a1fdf7dd9b31b2f4b1e588e0afbe5','official',NULL,NULL,'Ocean Currents and Tides'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--6',1,'{"question":"What is upwelling?","choices":["The sinking of dense surface water","The downward movement of sediment alone","The increase in local sea level during high tide","The rise of deeper water toward the surface"],"answer":3,"explanation":""}'::jsonb,'81b277dae1b68e2bdb092d08949e3250','official',NULL,NULL,'Ocean Currents and Tides'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--7',1,'{"question":"What does thermohaline circulation depend on?","choices":["Only surface waves caused by nearby boats","Water-density differences related to temperature and salinity","Only coastal tide height","Only wind speed, without water-density effects"],"answer":1,"explanation":""}'::jsonb,'5f9cb32988408be6d37a55c39a8b0bc5','official',NULL,NULL,'Ocean Currents and Tides'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--8',1,'{"question":"Why do winds drive many surface ocean currents?","choices":["They transfer momentum to surface water","Wind directly changes every water molecule''s density","Currents can occur only where waves break","Wind prevents ocean water from being influenced by rotation"],"answer":0,"explanation":""}'::jsonb,'9f36ee9211203cad0caad23f28450252','official',NULL,NULL,'Ocean Currents and Tides'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--9',1,'{"question":"How does Earth''s rotation influence large-scale ocean currents?","choices":["It forces every current directly north","It deflects their paths through the Coriolis effect","It makes winds irrelevant to surface currents","It determines identical speeds for all currents"],"answer":1,"explanation":""}'::jsonb,'649fb1e5e01266777caa5f9b5a8ecf38','official',NULL,NULL,'Ocean Currents and Tides'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--10',1,'{"question":"How do currents affect climate near some coasts?","choices":["They make coastal climate independent of ocean temperature","They remove all seasonal changes from nearby land","They affect only salinity and never heat transfer","They transport heat between regions"],"answer":3,"explanation":""}'::jsonb,'7e5c763c3ac4a821e54bf0fbe14e3a84','official',NULL,NULL,'Ocean Currents and Tides'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--11',1,'{"question":"Why is upwelled water often important for marine food webs?","choices":["It removes most nutrients from sunlit water","It makes phytoplankton independent of light","It can supply nutrients to sunlit surface waters","It always reduces all primary production"],"answer":2,"explanation":""}'::jsonb,'ff21f9deaafbb30e7c147787eba21e58','official',NULL,NULL,'Ocean Currents and Tides'),
