('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--13',1,'{"question":"How does cooling generally affect seawater density above its freezing point at a fixed salinity?","choices":["Density becomes zero","Salinity must decrease to zero","Density increases","Density always decreases whenever seawater cools"],"answer":2,"explanation":""}'::jsonb,'c83d1ffbfa16effe3ff7d9a1846a38f4','official',NULL,NULL,'Ocean Currents and Tides'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--14',1,'{"question":"Why do spring tides occur near both new and full Moon?","choices":["Lunar effects vanish at both phases","Solar and lunar tidal effects reinforce along a similar line","Solar and lunar effects always cancel at both phases","The Moon stops exerting gravity at full Moon"],"answer":1,"explanation":""}'::jsonb,'e55698cd625e8ce76c68b984670068a3','official',NULL,NULL,'Ocean Currents and Tides'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--15',1,'{"question":"Why can coastal tide patterns differ between places?","choices":["Every coast must have identical daily tide timing","Only the local water color affects tidal patterns","Tidal patterns are independent of basin shape","Coastline shape, basin geometry, and local conditions modify tidal response"],"answer":3,"explanation":""}'::jsonb,'775101f5940e24fc3f86c8361a0b6526','official',NULL,NULL,'Ocean Currents and Tides'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--16',1,'{"question":"High tide is 3.5 m and low tide is 0.8 m above the same reference. What is the tidal range?","choices":["4.3 m","3.5 m","0.8 m","2.7 m"],"answer":3,"explanation":""}'::jsonb,'cc753a3d22719d87ea2a7c0f21b7a335','official',NULL,NULL,'Ocean Currents and Tides'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--17',1,'{"question":"Which pair of water conditions most favors high density, compared with warmer, fresher water?","choices":["Warm and fresh","Cold and salty","Warm and less salty","Water temperature and salinity do not affect density"],"answer":1,"explanation":""}'::jsonb,'ea8d4ef9e56ad71aae2877705e2dc376','official',NULL,NULL,'Ocean Currents and Tides'),
('original:science--earth-space-science--ocean-currents-and-tides:science--earth-space-science--ocean-currents-and-tides--18',1,'{"question":"A coastal site receives a warm current. Compared with an otherwise similar site receiving a cold current, what is a likely influence?","choices":["A guarantee of zero rainfall","A guarantee that the region has no winter","Higher coastal air temperatures","No influence on local air temperature"],"answer":2,"explanation":""}'::jsonb,'82593e7361fb341aaa22595eda8c1172','official',NULL,NULL,'Ocean Currents and Tides'),
