('original:science--earth-space-science--groundwater-and-watersheds:science--earth-space-science--groundwater-and-watersheds--1',1,'{"question":"What is groundwater?","choices":["Only water flowing in surface rivers","Water that exists only in caves","Water within connected pores and fractures below the water table","Water stored only inside living organisms"],"answer":2,"explanation":""}'::jsonb,'ced4c90077d46933adf28a448f615903','official',NULL,NULL,'Groundwater and Watersheds'),
('original:science--earth-space-science--groundwater-and-watersheds:science--earth-space-science--groundwater-and-watersheds--2',1,'{"question":"What is the water table?","choices":["The upper surface of the saturated groundwater zone","The bottom of every lake","The boundary between ocean water and ice","The surface of a rain cloud"],"answer":0,"explanation":""}'::jsonb,'d91b0ab3d9472a2ba123e2b6655d7184','official',NULL,NULL,'Groundwater and Watersheds'),
('original:science--earth-space-science--groundwater-and-watersheds:science--earth-space-science--groundwater-and-watersheds--3',1,'{"question":"What is an aquifer?","choices":["A rock unit that stores water but cannot transmit useful amounts","A geologic unit that stores and transmits usable amounts of groundwater","Only a large underground open cavern","Any dry layer above the water table"],"answer":1,"explanation":""}'::jsonb,'3098ed674598bdcaaf32ba4fb31d5829','official',NULL,NULL,'Groundwater and Watersheds'),
('original:science--earth-space-science--groundwater-and-watersheds:science--earth-space-science--groundwater-and-watersheds--4',1,'{"question":"What is groundwater recharge?","choices":["The removal of groundwater by pumping","The flow of groundwater out through a spring","The replenishment of groundwater by water entering an aquifer","The evaporation of water directly from a stream"],"answer":2,"explanation":""}'::jsonb,'ab684dee51619f70f901f55aa39e6014','official',NULL,NULL,'Groundwater and Watersheds'),
('original:science--earth-space-science--groundwater-and-watersheds:science--earth-space-science--groundwater-and-watersheds--5',1,'{"question":"What is permeability?","choices":["The fraction of a rock''s volume made of pores alone","How readily a material allows fluid to flow through connected spaces","The total mass of water above a rock layer","The rate of evaporation from a surface"],"answer":1,"explanation":""}'::jsonb,'a449b48e74affd956bc66fa80fda4c29','official',NULL,NULL,'Groundwater and Watersheds'),
('original:science--earth-space-science--groundwater-and-watersheds:science--earth-space-science--groundwater-and-watersheds--6',1,'{"question":"What is base flow in a stream?","choices":["Only rapid surface runoff during a storm","Only water evaporating from the stream","The uphill movement of water toward a drainage divide","Flow supported by groundwater discharge between storms"],"answer":3,"explanation":""}'::jsonb,'0033529ab3e9e86aac89877de95de858','official',NULL,NULL,'Groundwater and Watersheds'),
