('original:science--earth-space-science--groundwater-and-watersheds:science--earth-space-science--groundwater-and-watersheds--9',1,'{"question":"Why can pavement increase surface runoff?","choices":["It always adds connected pore space to the ground","It makes all precipitation enter the aquifer directly","It often reduces infiltration into the ground","It reduces streamflow after every storm"],"answer":2,"explanation":""}'::jsonb,'9b49d6e5d8e76d8f2923c4fc83f96b37','official',NULL,NULL,'Groundwater and Watersheds'),
('original:science--earth-space-science--groundwater-and-watersheds:science--earth-space-science--groundwater-and-watersheds--10',1,'{"question":"Why is porous rock not necessarily highly permeable?","choices":["Porosity and permeability always measure the same property","Pores may be poorly connected","Every porous rock allows equally rapid flow","Only pore volume matters, not connections between pores"],"answer":1,"explanation":""}'::jsonb,'5a6906d3b29c844bb4704d8e45709328','official',NULL,NULL,'Groundwater and Watersheds'),
('original:science--earth-space-science--groundwater-and-watersheds:science--earth-space-science--groundwater-and-watersheds--11',1,'{"question":"How can pollution at the ground surface affect groundwater?","choices":["Soil removes every contaminant completely","Groundwater never connects with surface infiltration","Only contaminants visible to the eye can move downward","Contaminants can move downward with infiltrating water"],"answer":3,"explanation":""}'::jsonb,'8ead857fa26a7944132e589ff793ac84','official',NULL,NULL,'Groundwater and Watersheds'),
('original:science--earth-space-science--groundwater-and-watersheds:science--earth-space-science--groundwater-and-watersheds--12',1,'{"question":"Why do activities upstream matter to people downstream?","choices":["Only rainfall at the river mouth influences downstream water","Flowing water can carry sediment and pollutants through the watershed","River flow prevents contaminants from traveling","Upstream and downstream sections never exchange water"],"answer":1,"explanation":""}'::jsonb,'a3f82ae3d1e310f2b32e1efccd42c2b7','official',NULL,NULL,'Groundwater and Watersheds'),
