('original:science--earth-space-science--groundwater-and-watersheds:science--earth-space-science--groundwater-and-watersheds--14',1,'{"question":"How can wetlands influence water moving through a watershed?","choices":["They prevent every flood regardless of rainfall","They remove every dissolved contaminant completely","They can store water and slow its release","They always speed all runoff directly to the outlet"],"answer":2,"explanation":""}'::jsonb,'984e5b3f492d44268007ed6a06c03ada','official',NULL,NULL,'Groundwater and Watersheds'),
('original:science--earth-space-science--groundwater-and-watersheds:science--earth-space-science--groundwater-and-watersheds--15',1,'{"question":"Why are recharge areas important for groundwater protection?","choices":["Recharge areas prevent water from reaching aquifers","Recharge areas are always the deepest part of an aquifer","Only pumping locations affect groundwater quality","Water entering there can replenish an aquifer and carry contaminants"],"answer":3,"explanation":""}'::jsonb,'bc63dace2354fa35e0ef8e41bd15a47f','official',NULL,NULL,'Groundwater and Watersheds'),
