('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--3',1,'{"question":"What is an inference?","choices":["An explanation or conclusion drawn from observations","A procedure for measuring length","A direct instrument reading only","A result that requires no evidence"],"answer":0,"explanation":""}'::jsonb,'c690946619dd04103c3ced6e2df2a3f0','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--4',1,'{"question":"What is a scientific theory?","choices":["A personal opinion about nature","A claim that has not been investigated","A rule that never needs evidence","A broad explanation supported by substantial evidence"],"answer":3,"explanation":""}'::jsonb,'bab0ba06e8386b345b4a80adf6783924','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--5',1,'{"question":"What is a scientific model?","choices":["A representation used to study or explain a system","A final answer that cannot be revised","A measurement with no uncertainty","An experiment without variables"],"answer":0,"explanation":""}'::jsonb,'43e9807b3334dcac6ed283f127a1c471','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--6',1,'{"question":"What does peer review involve?","choices":["Students choosing the most popular conclusion","Replacing data with a scientist''s reputation","Other qualified researchers evaluating scientific work","Publishing results without examining methods"],"answer":2,"explanation":""}'::jsonb,'ecfee9c6288392ba17b8643ee1ae7523','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--7',1,'{"question":"What does replication mean in scientific research?","choices":["Changing every result to match an expectation","Using the same graph twice in a report","Removing results that differ from a prediction","Repeating a study or its methods to check findings"],"answer":3,"explanation":""}'::jsonb,'b828a82f64aee284aa44a1e1c64bcdd9','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--8',1,'{"question":"Why should scientific explanations be open to revision?","choices":["Earlier evidence has no value","New evidence may show that an explanation is incomplete","Scientists must change conclusions on a schedule","Every explanation is equally well supported"],"answer":1,"explanation":""}'::jsonb,'622de399e2077ce7fbc7cab9c196f6a4','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--9',1,'{"question":"How does an observational study differ from a controlled experiment?","choices":["It cannot collect numerical data","It examines conditions without deliberately assigning a treatment","It never uses instruments","It must avoid forming any hypothesis"],"answer":1,"explanation":""}'::jsonb,'1219685d561a9596f2fb1968001f195f','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--10',1,'{"question":"Why does correlation alone not establish causation?","choices":["Related variables can never affect each other","Causation is possible only in chemistry","A relationship becomes causal whenever a graph is drawn","Another factor or a different causal direction may explain the relationship"],"answer":3,"explanation":""}'::jsonb,'f5cdcfca8ba0969cd855dabbe289b266','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--11',1,'{"question":"How does a scientific law usually differ from a theory?","choices":["A law describes a pattern, while a theory explains phenomena","A theory automatically becomes a law after enough time","A law is an unsupported guess and a theory is a measurement","Laws apply only to living organisms"],"answer":0,"explanation":""}'::jsonb,'5882656e4b0d4bf388262902f3179a74','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--12',1,'{"question":"Why should researchers describe their methods clearly?","choices":["It guarantees that every hypothesis is correct","It removes the need for recording data","It helps others evaluate and repeat the work","It makes conflicting evidence unnecessary"],"answer":2,"explanation":""}'::jsonb,'b0e53786dc3ac3a9f6caf0cfa7ef5e3b','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--13',1,'{"question":"What should researchers do when results contradict their hypothesis?","choices":["Examine the methods and reconsider the hypothesis in light of the evidence","Discard all contradictory measurements automatically","Report only the measurements that fit","Treat the hypothesis as proven despite the results"],"answer":0,"explanation":""}'::jsonb,'d8c05c40408bf8567be6d4cb8a3790af','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--14',1,'{"question":"Why are several independent lines of evidence useful?","choices":["They replace the need for reliable measurements","Agreement among different methods can strengthen confidence in an explanation","They guarantee there is no uncertainty","They make peer review unnecessary"],"answer":1,"explanation":""}'::jsonb,'781196bdf15b63b51fd602e4396f3cf5','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--15',1,'{"question":"Why must scientists distinguish evidence from interpretation?","choices":["Interpretations can never be useful","Evidence always explains itself completely","Readers need to see what was observed and how conclusions were drawn","Only interpretations belong in reports"],"answer":2,"explanation":""}'::jsonb,'e90c7a3ff232f75e275df98a390a47d0','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--16',1,'{"question":"A student notices leaves bending toward a window and proposes that light affects growth direction. Which statement is a testable explanatory hypothesis?","choices":["The leaves were observed near a window","The window faces east","The plant has six leaves","Light affects the direction of plant growth"],"answer":3,"explanation":""}'::jsonb,'5f4d7491f0aadbc1af7030951f49148a','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--17',1,'{"question":"More ice cream is sold on days with more swimming accidents. Which explanation should be considered before claiming a direct cause?","choices":["The two measurements must be fabricated","Ice cream sales prove that food causes every accident","Hot weather may increase both swimming and ice cream sales","Correlation makes other explanations impossible"],"answer":2,"explanation":""}'::jsonb,'69c157109fe9a540ca20fc7e7d3aa26c','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--18',1,'{"question":"Two studies reach different conclusions. What is the best next scientific step?","choices":["Compare their methods, data, and limitations","Accept whichever was published first","Choose the conclusion with the most memorable title","Ignore both without examining their evidence"],"answer":0,"explanation":""}'::jsonb,'632cc039a1644365d172e8d003002085','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--19',1,'{"question":"A model predicts a river will flood, but it excludes a newly built levee. What should researchers examine?","choices":["Whether models can ever use numbers","Whether the river has a name","Whether the prediction agrees with public opinion","How the missing feature affects the model''s assumptions and prediction"],"answer":3,"explanation":""}'::jsonb,'9a6a4bf97c79de6fd89164c7ee06dd36','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--scientific-investigations:science--inquiry-environment--scientific-investigations--20',1,'{"question":"Which conclusion best matches a single successful experiment?","choices":["The explanation is permanently proven for every situation","The findings support the hypothesis under the tested conditions","All alternative explanations have been eliminated","No further investigation is useful"],"answer":1,"explanation":""}'::jsonb,'f806981002c1c5d9cb8d229586c2f0cc','official',NULL,NULL,'Scientific Investigations'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--1',1,'{"question":"What is an independent variable in an experiment?","choices":["A factor deliberately changed by the investigator","The outcome being measured","A factor kept constant","An error in a measuring instrument"],"answer":0,"explanation":""}'::jsonb,'6ed1f9aa698f58f498efa9a9f6d14c81','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--2',1,'{"question":"What is a dependent variable?","choices":["A factor deliberately held constant","The outcome measured in response to a change","The name of the experimental group","A prediction written before testing"],"answer":1,"explanation":""}'::jsonb,'8cb01b436f9e38414f8079bb02cd89ae','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--3',1,'{"question":"What is a controlled variable?","choices":["An outcome that must increase","A treatment given only to one group","A factor kept consistent across comparison groups","A measurement removed from the results"],"answer":2,"explanation":""}'::jsonb,'322aea65f1472c635a011e9c2f04ae0e','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--4',1,'{"question":"What is the purpose of a control group?","choices":["To receive every possible treatment at once","To guarantee the expected result","To replace measurements with predictions","To provide a comparison for evaluating a treatment"],"answer":3,"explanation":""}'::jsonb,'d8dde280a429dc3c6ff7eb9a2f5565bb','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--5',1,'{"question":"What is a repeated trial?","choices":["A summary of someone else''s conclusion","A change in all experimental variables","Another run of a test under the same planned conditions","A prediction made after deleting data"],"answer":2,"explanation":""}'::jsonb,'9a072a21927bab4569ed03102100bb49','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--6',1,'{"question":"What is a confounding variable?","choices":["An additional factor that makes the treatment''s effect difficult to separate","A factor that is perfectly controlled","The numerical unit used in a graph","A measurement that agrees with a hypothesis"],"answer":0,"explanation":""}'::jsonb,'d13c270687062f3cfd0857195fffc34c','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--7',1,'{"question":"What does random assignment mean?","choices":["Choosing only volunteers who expect success","Using chance to place participants or subjects into treatment groups","Assigning groups by alphabetical order","Giving every group the same treatment"],"answer":1,"explanation":""}'::jsonb,'de1f62b76113c879777604e8a762f4c7','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--8',1,'{"question":"Why should comparison groups be similar before a treatment begins?","choices":["Similar groups eliminate all measurement uncertainty","Differences should be introduced after the results are known","Only identical outcomes can be compared","Initial differences could otherwise explain the results"],"answer":3,"explanation":""}'::jsonb,'ccaa499f6f51ab1d7b7dd44362b64f71','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--9',1,'{"question":"Why is changing one main variable at a time often helpful?","choices":["It makes repeated trials unnecessary","It prevents all variation among subjects","It makes the effect of that variable easier to interpret","It ensures the hypothesis is supported"],"answer":2,"explanation":""}'::jsonb,'e7d92f64b5d8b006e321ea8b876848de','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--10',1,'{"question":"Why can more repeated trials improve an investigation?","choices":["They help reveal variation and reduce the influence of unusual results","They remove the need for a control group","They guarantee every measurement is identical","They allow researchers to select only favorable results"],"answer":0,"explanation":""}'::jsonb,'a5bbef225c12c1a13cc964f229f49875','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--11',1,'{"question":"How does random sampling differ from random assignment?","choices":["Sampling applies treatments; assignment selects measuring units","They always mean exactly the same thing","Sampling eliminates all bias; assignment eliminates all uncertainty","Sampling selects subjects from a population; assignment places them in study groups"],"answer":3,"explanation":""}'::jsonb,'480532d5e9a55ee09be34ca0a2a5b8ab','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--12',1,'{"question":"Why should investigators decide how to measure an outcome before collecting data?","choices":["It makes actual measurements optional","It promotes consistent measurements and reduces selective interpretation","It allows the outcome to be changed whenever results disagree","It ensures that no unexpected result occurs"],"answer":1,"explanation":""}'::jsonb,'ed8c2725f58db88095cbf2d1139b21be','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--13',1,'{"question":"Why can blinding an observer improve an experiment?","choices":["It allows subjects to be measured without consent","It prevents instruments from recording data","It guarantees no confounding variables exist","Knowing the treatment can unintentionally influence observations"],"answer":3,"explanation":""}'::jsonb,'a1ee9f8d1a8a15f2db8744955c26634e','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--14',1,'{"question":"What is a limitation of testing a treatment on only one organism?","choices":["Organisms cannot be measured","A single organism always represents its species perfectly","Individual differences may be mistaken for a treatment effect","Control groups are useful only with large organisms"],"answer":2,"explanation":""}'::jsonb,'1befd1b382601d1e65e8ce120c24b3d0','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--15',1,'{"question":"What makes an experimental conclusion appropriately cautious?","choices":["It states that the treatment works in every possible setting","It considers the tested conditions and the study''s limitations","It ignores any variation in the results","It treats the original prediction as evidence"],"answer":1,"explanation":""}'::jsonb,'504ba4100ef6d84517ebcac2ee463fed','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--16',1,'{"question":"Plants receive different fertilizer amounts, and their final heights are measured. What is the dependent variable?","choices":["Final plant height","Plant species","Pot size","Fertilizer amount"],"answer":0,"explanation":""}'::jsonb,'3c7668ea6f4c0cbed5bc7ac15d48fed9','official',NULL,NULL,'Experimental Design')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--17',1,'{"question":"A student tests light''s effect on plant growth. Which factor should be kept consistent?","choices":["The amount of light being tested","The amount of water supplied","The resulting plant height","The difference between the groups'' results"],"answer":1,"explanation":""}'::jsonb,'66b5a5161bf56c70bffb146633f39318','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--18',1,'{"question":"A fertilizer group gets more water than a comparison group. Why is the conclusion uncertain?","choices":["Water cannot affect plants","The comparison group becomes an independent variable","The fertilizer must have no effect","The effects of fertilizer and water are confounded"],"answer":3,"explanation":""}'::jsonb,'bcf3aa648530a7ae753775867dcf004a','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--19',1,'{"question":"A new filter is tested with muddy water. What makes a useful comparison?","choices":["Compare filtered and unfiltered samples from the same starting mixture","Use clearer water for the new filter","Test untreated water from a different source only","Measure only the filter''s color"],"answer":0,"explanation":""}'::jsonb,'5dcfe69c17c00aaceacede90275b00f3','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--experimental-design:science--inquiry-environment--experimental-design--20',1,'{"question":"A researcher tests a material''s strength using one sample, which breaks unusually early. What improvement best checks whether this result is typical?","choices":["Report the result without recording the procedure","Change the strength unit after the test","Test multiple comparable samples with the same procedure","Assume all samples will break at the same point"],"answer":2,"explanation":""}'::jsonb,'0da7667e17c8eb6fc59f038325e31cb2','official',NULL,NULL,'Experimental Design'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--1',1,'{"question":"Which SI base unit measures length?","choices":["Newton","Liter","Gram","Meter"],"answer":3,"explanation":""}'::jsonb,'149a5155d106cde447ff683ae886c4c5','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--2',1,'{"question":"Which SI base unit measures mass?","choices":["Kilogram","Meter","Second","Pascal"],"answer":0,"explanation":""}'::jsonb,'8395e6363ae955f4c6c3f44865ddace4','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--3',1,'{"question":"Which SI base unit measures time?","choices":["Kelvin","Second","Ampere","Joule"],"answer":1,"explanation":""}'::jsonb,'090ebfaff3095e90c6ddb854990ff91d','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--4',1,'{"question":"Which SI base unit measures temperature?","choices":["Degree Celsius","Watt","Kelvin","Newton"],"answer":2,"explanation":""}'::jsonb,'9a5515c92e627b844702d0eff3437d9f','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--5',1,'{"question":"What does the prefix kilo- indicate?","choices":["One hundredth of the base unit","One thousand times the base unit","One millionth of the base unit","One tenth of the base unit"],"answer":1,"explanation":""}'::jsonb,'03070ac2de7893942a2613715273489b','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--6',1,'{"question":"What does the prefix milli- indicate?","choices":["One hundred times the base unit","One hundredth of the base unit","One thousand times the base unit","One thousandth of the base unit"],"answer":3,"explanation":""}'::jsonb,'61f0407d841a00c7e4446a9a1184e01c','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--7',1,'{"question":"Which instrument is commonly used to measure liquid volume in a laboratory?","choices":["Graduated cylinder","Stopwatch","Spring scale","Meterstick"],"answer":0,"explanation":""}'::jsonb,'8d3e8770a3640ad1c85c18ccbb8a2b0c','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--8',1,'{"question":"Why must a numerical measurement include its unit?","choices":["Units guarantee that the value is correct","Units replace the need for an instrument","Units identify the quantity''s scale and meaning","Every quantity uses the same unit"],"answer":2,"explanation":""}'::jsonb,'c09210a5214eaeff299c887d2def5c88','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--9',1,'{"question":"What is precision in repeated measurements?","choices":["How many different units are used","How close a measurement is to the accepted value","How large the measuring instrument is","How closely the measurements agree with each other"],"answer":3,"explanation":""}'::jsonb,'20a2a639e2c60b9890588fb71af0c221','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--10',1,'{"question":"What is accuracy?","choices":["The number of repeated trials alone","How close a measured value is to the accepted value","How similar incorrect measurements are to one another","The number of digits displayed regardless of instrument quality"],"answer":1,"explanation":""}'::jsonb,'76d486215509e479ec2138a2128e61ed','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--11',1,'{"question":"Why should a scale be zeroed before measuring an object''s mass?","choices":["To make the object lighter","To change kilograms into meters","To avoid including an unwanted offset in the reading","To remove all possible uncertainty"],"answer":2,"explanation":""}'::jsonb,'504792583a5443314e5a89e84fb06697','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--12',1,'{"question":"How should the bottom of a concave water meniscus usually be read?","choices":["At eye level with the liquid surface","At the highest edge while tilting the cylinder","From below the cylinder''s base","From far above the cylinder"],"answer":0,"explanation":""}'::jsonb,'62482a540903b16b2ca4e28691462262','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--13',1,'{"question":"Why do measurements have uncertainty?","choices":["Units change randomly during a test","All scientific measurements are guesses","Instruments and procedures have limited resolution and other sources of variation","Repeated measurements cannot be compared"],"answer":2,"explanation":""}'::jsonb,'99a60851fc2d380c5cb0bbe6bbe58a9a','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--14',1,'{"question":"Why is a digital display with many digits not sufficient evidence of accuracy?","choices":["Digital instruments never work correctly","Extra digits eliminate the need for units","A display can measure only time","An instrument can display many digits while having calibration errors"],"answer":3,"explanation":""}'::jsonb,'dc3a531d4ac4e37e38350c50ad213c49','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--15',1,'{"question":"Why should a scientist use an appropriate instrument range?","choices":["The instrument must accommodate the quantity and provide useful resolution","Instrument range does not affect usefulness","Any ruler can resolve microscopic structures","The largest instrument is always the most precise"],"answer":0,"explanation":""}'::jsonb,'4da680d7366e170b46a8a00cc255fd3f','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--16',1,'{"question":"A distance is 2.5 kilometers. What is it in meters?","choices":["25 meters","2,500 meters","25,000 meters","250 meters"],"answer":1,"explanation":""}'::jsonb,'737a4ab65259c16c30ed8f450ce9ad16','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--17',1,'{"question":"A sample has a volume of 3.25 liters. What is it in milliliters?","choices":["3,250 milliliters","325 milliliters","32.5 milliliters","0.00325 milliliters"],"answer":0,"explanation":""}'::jsonb,'9132c2bd0e69a82827137c4a1292e396','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--18',1,'{"question":"Repeated readings are 102.0 g for a 100.0 g standard; the stated measurement uncertainty is ±0.1 g. How should these results be described?","choices":["Accurate but not precise","Neither accurate nor precise","Precise but not accurate","Both accurate and precise"],"answer":2,"explanation":""}'::jsonb,'885abd5b7a319aa8107d8661f7122bd4','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--19',1,'{"question":"A ruler has marks every millimeter. Which recorded value most clearly overstates what this ruler alone can support?","choices":["18 millimeters","18.234567 millimeters","18.2 millimeters","18 centimeters"],"answer":1,"explanation":""}'::jsonb,'7056d5ccceb699eb31e640e9b1934253','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--measurement-and-si-units:science--inquiry-environment--measurement-and-si-units--20',1,'{"question":"A container''s mass is 40 grams, and the container plus sand has a mass of 135 grams. What is the sand''s mass?","choices":["175 grams","135 grams","40 grams","95 grams"],"answer":3,"explanation":""}'::jsonb,'2bc9ed98fd61e00eab00e81aff05b807','official',NULL,NULL,'Measurement and SI Units'),
('original:science--inquiry-environment--data-and-graphs:science--inquiry-environment--data-and-graphs--1',1,'{"question":"What does a graph''s horizontal axis usually show in a simple experiment?","choices":["The investigator''s conclusion","Only the graph''s title","The independent variable","The dependent variable in every experiment"],"answer":2,"explanation":""}'::jsonb,'a1b06d01691de78472de59caca9d1c96','official',NULL,NULL,'Data and Graphs'),
('original:science--inquiry-environment--data-and-graphs:science--inquiry-environment--data-and-graphs--2',1,'{"question":"What does a graph''s vertical axis usually show in a simple experiment?","choices":["Only the instrument name","The control group''s label in every experiment","Only the date of publication","The dependent variable"],"answer":3,"explanation":""}'::jsonb,'abf11b2c6e14020e5f608277aef4a819','official',NULL,NULL,'Data and Graphs'),
('original:science--inquiry-environment--data-and-graphs:science--inquiry-environment--data-and-graphs--3',1,'{"question":"Which graph is generally best for comparing separate categories?","choices":["Bar graph","Unlabeled line graph","Scatterplot with no category labels","Map without a scale"],"answer":0,"explanation":""}'::jsonb,'9ed693496e828aa83ac31ac87e13b24e','official',NULL,NULL,'Data and Graphs'),
