('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--1',1,'{"question":"What is a renewable resource?","choices":["A resource replenished naturally on a relevant human time scale","A resource that can never be depleted","Any resource formed deep underground","A resource used only once"],"answer":0,"explanation":""}'::jsonb,'1c5e473c2c6207ef1557ef44ebe57731','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--2',1,'{"question":"Which resource is nonrenewable on human time scales?","choices":["Sunlight","Wind","Coal","Flowing water"],"answer":2,"explanation":""}'::jsonb,'388559cf6c6c0d5c4c03cc924c7c1032','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--3',1,'{"question":"What does resource conservation mean?","choices":["Using a resource as quickly as possible","Ending all use of every natural material","Replacing all renewable resources with fossil fuels","Reducing unnecessary use and protecting supplies"],"answer":3,"explanation":""}'::jsonb,'abc83c3a7ddfbf01a56c95ec23b7e9a1','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--4',1,'{"question":"What is reuse?","choices":["Breaking a material into raw inputs","Using an item again without first processing it into raw material","Discarding a product after one use","Burning a material to obtain energy"],"answer":1,"explanation":""}'::jsonb,'dae38274b5de196995dc2e497260f346','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--5',1,'{"question":"What is recycling?","choices":["Storing every discarded item indefinitely","Using a product again without processing","Using only newly mined resources","Processing discarded materials into materials for new products"],"answer":3,"explanation":""}'::jsonb,'3bd3ac71b2da9cd2edfc91842e6d870d','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--6',1,'{"question":"What is a watershed?","choices":["An area of land that drains to a common water body","A layer of rock with no water movement","An isolated cloud above a forest","Only the deepest part of an ocean"],"answer":0,"explanation":""}'::jsonb,'5adbb88b0507b5775f4f5dcf7e2c9255','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--7',1,'{"question":"What does biodiversity refer to?","choices":["Only the number of people in a region","Only the age of a forest","The variety of life, including genetic, species, and ecosystem diversity","The amount of rainfall in one storm"],"answer":2,"explanation":""}'::jsonb,'cd8628b1fd87f01cbdb18660cc4f1a2c','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--8',1,'{"question":"Why can a renewable forest resource still be depleted?","choices":["Trees cannot regrow under any conditions","Harvesting can exceed regrowth and damage the ecosystem","All forests grow at the same rate","Renewable means that harvesting has no effect"],"answer":1,"explanation":""}'::jsonb,'50cafe3311c22e3b0de45e3a15b80970','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--9',1,'{"question":"Why can reducing consumption save more resources than recycling alone?","choices":["Recycling always uses more resources than making new products","It avoids some material extraction and production before waste is created","Consumption has no connection to waste","All materials can be recycled indefinitely without losses"],"answer":1,"explanation":""}'::jsonb,'373d3b99782c98a3a706b26824a61f89','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--10',1,'{"question":"How can excess fertilizer runoff harm a lake?","choices":["It can promote algal growth whose decomposition reduces dissolved oxygen","It directly turns fresh water into salt water","It prevents all plant growth immediately","It always cools the water below freezing"],"answer":0,"explanation":""}'::jsonb,'5e18b2bba88ccdc91e5506b82e3528b2','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--11',1,'{"question":"Why can vegetation along a stream help protect water quality?","choices":["It prevents all rainfall from reaching the stream","It produces unlimited clean water","It makes pollutants evaporate instantly","It can trap sediment and reduce nutrient runoff"],"answer":3,"explanation":""}'::jsonb,'dde062b554170ce63affc59434c099c9','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--12',1,'{"question":"Why should environmental decisions consider a product''s entire life cycle?","choices":["Only disposal has environmental effects","Only manufacturing uses energy","Extraction, production, use, and disposal can each have impacts","Transport cannot affect resource use"],"answer":2,"explanation":""}'::jsonb,'cdb59050867c8e4068987b26aa7e5bba','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--13',1,'{"question":"What distinguishes energy efficiency from simply using a device less often?","choices":["Efficiency means replacing all electricity with chemical fuel","Efficiency means using the same device for fewer hours only","Efficiency measures total fuel use without considering output","Efficiency provides a comparable service using less energy"],"answer":3,"explanation":""}'::jsonb,'87eb131d5fc25a87b08d38dd0dbecbea','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--14',1,'{"question":"Why can groundwater be depleted despite being replenished by rain?","choices":["Groundwater cannot move through rock","Withdrawal can exceed the rate of recharge","Rainwater never reaches underground aquifers","Every aquifer refills completely each day"],"answer":1,"explanation":""}'::jsonb,'c923a5feff3ac3852d62c2a10f173d2b','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--15',1,'{"question":"Why can habitat fragmentation reduce biodiversity?","choices":["It can isolate populations and limit movement between habitats","It guarantees that all species adapt quickly","It always increases habitat size","It removes all competition among organisms"],"answer":0,"explanation":""}'::jsonb,'d68d861450c068da4efb2121930d7d20','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--16',1,'{"question":"A forest regrows 100 units of timber yearly but loses 150 units to harvest yearly. What does this pattern suggest if it continues?","choices":["The timber supply must increase","Harvest and regrowth are balanced","The timber supply will decline","Regrowth will automatically increase to match harvest"],"answer":2,"explanation":""}'::jsonb,'70f59465b725445348efd1bef6929b6d','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--17',1,'{"question":"Two lamps provide the same useful light, but one uses half as much electricity. Which lamp is more energy-efficient?","choices":["Both must have the same efficiency","The lamp using twice as much electricity","The lamp using half as much electricity","Efficiency cannot be compared without knowing their color"],"answer":2,"explanation":""}'::jsonb,'4462dca71a2b86fe4f2a631e14aee697','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--18',1,'{"question":"A town wants to reduce discarded drink containers. Which action most directly prevents waste generation?","choices":["Increase production of disposable containers","Send every container to a larger landfill","Collect more containers only after disposal","Use durable refillable containers repeatedly"],"answer":3,"explanation":""}'::jsonb,'41d0564915be074e321a16c7ce65be59','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--19',1,'{"question":"A proposed energy project has low operating emissions but affects wildlife habitat. What is a sound evaluation approach?","choices":["Ignore habitat effects because emissions are low","Compare multiple impacts, benefits, and possible mitigation measures","Reject all evidence about the project''s benefits","Assume every energy source has identical environmental effects"],"answer":1,"explanation":""}'::jsonb,'a4fcd05d1e9fc332c4790a8921cab715','official',NULL,NULL,'Environmental Resources and Sustainability'),
('original:science--inquiry-environment--environmental-resources-and-sustainability:science--inquiry-environment--environmental-resources-and-sustainability--20',1,'{"question":"An aquifer receives about 10 million liters of recharge annually while pumping removes 14 million liters. Which change most directly addresses the imbalance?","choices":["Reduce withdrawals or increase feasible recharge while monitoring aquifer conditions","Measure only one well once","Assume recharge rises whenever pumping rises","Pump faster during dry periods"],"answer":0,"explanation":""}'::jsonb,'2ae1a6039b6ea305ff4af1f24c79eb7c','official',NULL,NULL,'Environmental Resources and Sustainability'),
