('original:science--inquiry-environment--laboratory-safety:science--inquiry-environment--laboratory-safety--10',1,'{"question":"Why should unused chemicals not be returned to a stock container?","choices":["Stock chemicals always have unlimited purity","Returning chemicals makes the container lighter","All chemicals become harmless after one use","They may contaminate the shared supply"],"answer":3,"explanation":""}'::jsonb,'b8ce6496c67a19fdda66dea3358c18ad','official',NULL,NULL,'Laboratory Safety'),
('original:science--inquiry-environment--laboratory-safety:science--inquiry-environment--laboratory-safety--11',1,'{"question":"Why is a clear, uncluttered work area important?","choices":["It reduces contamination, spills, and trip hazards","It guarantees every experiment''s hypothesis","It eliminates the need for supervision","It prevents all instrument uncertainty"],"answer":0,"explanation":""}'::jsonb,'b78cf75d2c7e691f98504ccdb4e55d27','official',NULL,NULL,'Laboratory Safety'),
('original:science--inquiry-environment--laboratory-safety:science--inquiry-environment--laboratory-safety--12',1,'{"question":"Why should glassware be inspected before use?","choices":["Appearance establishes chemical purity","All glass is safe at every temperature","Cracks or damage can make it unsafe","Glass damage affects only the printed labels"],"answer":2,"explanation":""}'::jsonb,'56b49684a697a942305f36490eca2151','official',NULL,NULL,'Laboratory Safety'),
('original:science--inquiry-environment--laboratory-safety:science--inquiry-environment--laboratory-safety--13',1,'{"question":"Why should students learn emergency-equipment locations before an activity?","choices":["They should use all equipment without instruction","Equipment replaces every prevention measure","They need to follow trained emergency procedures promptly","Every emergency uses the same response"],"answer":2,"explanation":""}'::jsonb,'4bd2eea70b18ed858f5d9f764c05ac25','official',NULL,NULL,'Laboratory Safety'),
('original:science--inquiry-environment--laboratory-safety:science--inquiry-environment--laboratory-safety--14',1,'{"question":"Why are gloves not a replacement for proper hygiene and handling?","choices":["They can become contaminated and must be used appropriately","Gloves eliminate all chemical hazards","Gloves make every substance safe to taste","Gloves guarantee no transfer to other surfaces"],"answer":0,"explanation":""}'::jsonb,'f6b01568f625e78259d667f9086e8530','official',NULL,NULL,'Laboratory Safety'),
