('original:science--inquiry-environment--laboratory-safety:science--inquiry-environment--laboratory-safety--16',1,'{"question":"A student finds an unlabeled liquid. What should the student do?","choices":["Identify it by tasting a drop","Avoid using it and notify the teacher","Mix it with another liquid to see what happens","Assume it is water because it is clear"],"answer":1,"explanation":""}'::jsonb,'4fc17bd6fc386b7d87929eb2e0f26913','official',NULL,NULL,'Laboratory Safety'),
