('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--2',1,'{"question":"What is a mathematical model?","choices":["A claim that mathematics removes all uncertainty","A physical replica that must be full-sized","A representation using mathematical relationships","A list containing only instrument names"],"answer":2,"explanation":""}'::jsonb,'2bce4ecfc15a5c2e35e4c01bf2a271c5','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--3',1,'{"question":"What is a conceptual model?","choices":["A measurement of an object''s exact mass","A representation of how components and processes relate","A claim that cannot be compared with evidence","A model containing every detail of reality"],"answer":1,"explanation":""}'::jsonb,'94dd8949715d65c81066cb03ed8cedfa','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--4',1,'{"question":"What is a model assumption?","choices":["An observed fact that can never change","The final answer in every investigation","An instrument''s serial number","A condition or simplification accepted for constructing the model"],"answer":3,"explanation":""}'::jsonb,'4e0b582e8faaba1d90ee26f2920c6ea1','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--5',1,'{"question":"What is a model prediction?","choices":["A measurement already collected in every case","The model''s publication date","An expected outcome derived from the model","A personal preference about a result"],"answer":2,"explanation":""}'::jsonb,'cabad8f686d9886c9fd3b737e4c7dce4','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--6',1,'{"question":"What does model validation involve?","choices":["Making every input equal to zero","Judging only how attractive the model looks","Assuming agreement without testing","Comparing model performance with relevant independent observations"],"answer":3,"explanation":""}'::jsonb,'b9ab33b6da31eac750d86d910302acbe','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--7',1,'{"question":"What is a simulation?","choices":["A guarantee that no measurement error exists","A representation that imitates a system''s behavior over time or under conditions","A complete replacement for all observations","A classification rank"],"answer":1,"explanation":""}'::jsonb,'e55ebb8b00a4703fb27daf13bee13abd','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--8',1,'{"question":"Why do models simplify real systems?","choices":["They emphasize useful features while making analysis manageable","They must omit every important process","They eliminate the need for evidence","They prove systems have only one component"],"answer":0,"explanation":""}'::jsonb,'fc5988d30c7325439ab4536783455241','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--9',1,'{"question":"Why can two models of the same system both be useful?","choices":["They must make identical assumptions","Only the older model can be scientific","They may address different questions or levels of detail","Neither can be compared with observations"],"answer":2,"explanation":""}'::jsonb,'1e8d9c42e2255fea4b94bc49502b5b62','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--10',1,'{"question":"Why should a model''s applicable range be stated?","choices":["Its assumptions may work under some conditions but fail under others","Models work perfectly at every scale","A range specifies only the author''s age","Applicable ranges make tests unnecessary"],"answer":0,"explanation":""}'::jsonb,'01b3d70368bac68551478d36220aa374','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--11',1,'{"question":"How can a model be improved after repeated mismatches with observations?","choices":["Remove all observations that disagree","Declare every mismatch irrelevant","Add detail without evaluating its effects","Revise assumptions or relationships and test the revised model"],"answer":3,"explanation":""}'::jsonb,'56ab102c93a2f75c205ed04ba3453299','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--12',1,'{"question":"Why is a scale-model river not necessarily a perfect replica of real flow?","choices":["Water behaves identically at all sizes","Scaling can change relationships among forces and dimensions","Only color matters in fluid motion","Physical models cannot use real water"],"answer":1,"explanation":""}'::jsonb,'2f5531f9ddaf84bdf3dcf22126cc016d','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--13',1,'{"question":"Why can sensitivity analysis help evaluate a model?","choices":["It proves all inputs are measured exactly","It reveals how outputs change when inputs or assumptions vary","It forces every prediction to stay constant","It measures only the model''s physical weight"],"answer":1,"explanation":""}'::jsonb,'2372ae57dd6a649f369f97ce8f8175d3','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--14',1,'{"question":"Why is testing on independent data useful after fitting a model?","choices":["It guarantees that the model works forever","It makes the fitting data unnecessary to report","It prevents any further revision","It helps assess performance beyond the data used to tune it"],"answer":3,"explanation":""}'::jsonb,'ce91afba7e58ee628f84e82e0e3dc02b','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--15',1,'{"question":"How should uncertainty in model inputs be treated?","choices":["Consider how it may affect predictions","Assume every input is exact","Replace every uncertain value with zero","Ignore it if the model uses equations"],"answer":0,"explanation":""}'::jsonb,'9fc6345f696b27617f0315cf06fa9860','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--16',1,'{"question":"A globe preserves Earth''s overall shape but omits individual buildings. What is the best assessment?","choices":["It cannot be a model because it omits detail","It predicts every building''s location exactly","It is useful for some geographic questions but not every question","It is useful only if made at Earth''s full size"],"answer":2,"explanation":""}'::jsonb,'54f87589b718d811a60216883148ef71','official',NULL,NULL,'Scientific Models')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--17',1,'{"question":"A model assumes constant birth rates, but rates change during a drought. What should be examined?","choices":["Whether numbers should be removed entirely","Whether all earlier observations were false","Whether drought can be ignored by definition","Whether the assumption affects the model''s predictions"],"answer":3,"explanation":""}'::jsonb,'9fd6c25c02a9b31e8160ace05406ed06','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--18',1,'{"question":"Two climate simulations differ when one input changes. What can this comparison help reveal?","choices":["The exact future climate without uncertainty","The prediction''s sensitivity to that input","Which model is universally correct without testing either one","That observations are unnecessary"],"answer":1,"explanation":""}'::jsonb,'4742334d3a524acea3951ec5b5482b67','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--19',1,'{"question":"A model predicts 20 units under tested conditions, while repeated reliable measurements are near 35. What is an appropriate response?","choices":["Change measurements to 20","Accept 20 solely because it came from a model","Investigate the mismatch and revise or limit the model as needed","Conclude that all scientific models are useless"],"answer":2,"explanation":""}'::jsonb,'078c1f0fe63e9cad3b1a9e0ed73ef43d','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--scientific-models:science--inquiry-environment--scientific-models--20',1,'{"question":"A traffic model accurately predicts morning congestion but fails during road closures. What conclusion is justified?","choices":["Its usefulness depends on whether closure conditions are represented","It must predict every possible traffic condition","All morning predictions must therefore be wrong","It has no assumptions"],"answer":0,"explanation":""}'::jsonb,'7cdf0e704bf27dac1ee9a642e53d4488','official',NULL,NULL,'Scientific Models'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--1',1,'{"question":"What is a scientific claim?","choices":["A raw measurement with no interpretation","A statement proposed as an answer or explanation","An instrument''s unit symbol","A bibliography entry only"],"answer":1,"explanation":""}'::jsonb,'8284f8d5c8dcbfce20c0327c5081d249','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--2',1,'{"question":"What counts as empirical evidence?","choices":["The popularity of an idea alone","An author''s confidence alone","A preferred outcome","Relevant observations or measurements"],"answer":3,"explanation":""}'::jsonb,'5a412a2eddaecc478aa3c0e11bbf9b93','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--3',1,'{"question":"What is reasoning in a claim-evidence-reasoning explanation?","choices":["The connection between evidence and claim using scientific principles","A repetition of the title","A list of equipment only","An unsupported opinion"],"answer":0,"explanation":""}'::jsonb,'f37083056bcb426f17d5830b4b9f156d','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--4',1,'{"question":"What is a counterargument?","choices":["A requirement to reject all evidence","A second copy of the same conclusion","An alternative explanation or challenge to a claim","A measurement unit"],"answer":2,"explanation":""}'::jsonb,'9f04f26ce8c2e73617acba5dbab7e90c','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--5',1,'{"question":"What is a limitation of evidence?","choices":["Proof that every result is false","A reason never to collect more data","An explanation unrelated to methods","A factor restricting what the evidence can support"],"answer":3,"explanation":""}'::jsonb,'4b09ae2c0406885aa066b1ff0600c991','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--6',1,'{"question":"What is anecdotal evidence?","choices":["A carefully sampled population measurement in every case","A complete controlled experiment by definition","An individual account that may not represent a broader pattern","A mathematical proof"],"answer":2,"explanation":""}'::jsonb,'c2c83b642f9e6d932f72f4abe0a99a9a','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--7',1,'{"question":"What is confirmation bias?","choices":["Favoring information that supports an existing belief","Recording data before forming a conclusion","Considering contradictory results fairly","Reporting uncertainty explicitly"],"answer":0,"explanation":""}'::jsonb,'36e7969e7c18a5a9b4bb6ac2d6e8bd89','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--8',1,'{"question":"Why should evidence be relevant to the specific claim?","choices":["Any number supports every scientific claim","A true observation may still fail to address the proposed explanation","Relevance depends only on source popularity","Measurements always have identical meanings"],"answer":1,"explanation":""}'::jsonb,'9b0941c9eb4e2163e01a599889a96eb8','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--9',1,'{"question":"Why can a large sample help support a population-level conclusion?","choices":["It automatically removes every sampling bias","It guarantees causation","It makes measurement quality irrelevant","It can reduce random sampling variation when collected appropriately"],"answer":3,"explanation":""}'::jsonb,'43686d2b2ea16cdb5256669c1d8615b8','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--10',1,'{"question":"Why should alternative explanations be considered?","choices":["Science requires accepting all explanations equally","More than one process may fit the same observations","Alternatives replace the need for data","A claim cannot be revised once written"],"answer":1,"explanation":""}'::jsonb,'8dac3329a3dba7cf584bfd1916cbdf2f','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--11',1,'{"question":"Why is uncertainty part of a strong scientific argument?","choices":["It proves that no knowledge is possible","It means the evidence must be hidden","It makes the strength and limits of the inference clearer","It requires choosing the least likely conclusion"],"answer":2,"explanation":""}'::jsonb,'8c1a15600c5649b666b05e3dcff55600','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--12',1,'{"question":"Why should a scientific argument separate observation from interpretation?","choices":["Readers need to identify what was measured and what was inferred","Interpretations are always direct measurements","Observations cannot be communicated","Only personal opinions belong in conclusions"],"answer":0,"explanation":""}'::jsonb,'d35f37d83d8527cae6c526b32a460807','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--13',1,'{"question":"Why is a scientist''s authority alone insufficient evidence?","choices":["The claim still requires methods and data that can be evaluated","Qualified scientists never produce useful work","Credentials determine every experimental result","Scientific claims are settled by voting"],"answer":0,"explanation":""}'::jsonb,'93901932cfbeec8144c5fd569936a195','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--14',1,'{"question":"How should conflicting reliable evidence be handled?","choices":["Choose only the preferred result","Assume the later result must be false","Compare methods, conditions, and possible explanations for the difference","Combine unrelated values without examining context"],"answer":2,"explanation":""}'::jsonb,'f9cf59b3006056775d3bdb3b324365cf','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--15',1,'{"question":"What strengthens an argument about a causal effect?","choices":["A graph with two trending variables alone","Evidence that addresses competing explanations and isolates the proposed cause","A single testimonial alone","A conclusion chosen before collecting observations"],"answer":1,"explanation":""}'::jsonb,'c63d8bcbc054854e1b1b44b65e08a503','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--16',1,'{"question":"A claim says a fertilizer improves growth. The evidence is only the fertilizer''s color. What is the main weakness?","choices":["The claim must be true because color is observable","Any observation automatically measures growth","A fertilizer''s appearance determines its effect on all plants","The evidence does not measure the claimed growth effect"],"answer":3,"explanation":""}'::jsonb,'f0180a331f9f3345dbaa1544b1a4984d','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--17',1,'{"question":"One plant grows better after treatment, but no comparison plants are measured. What conclusion is most appropriate?","choices":["The treatment is proven effective for all plants","The result proves that sunlight has no effect","The observation alone does not isolate the treatment''s effect","Further measurements cannot improve the evidence"],"answer":2,"explanation":""}'::jsonb,'4d5792eeb44c416c240336e759bb13c3','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--18',1,'{"question":"Two materials are compared in repeated fair tests; one consistently transfers less heat. Which claim is best supported?","choices":["Under tested conditions, it is the better thermal insulator","It is the strongest material under every load","It never transfers any energy","It is better for every possible engineering purpose"],"answer":0,"explanation":""}'::jsonb,'6d6879a360bea1d52b5c47c8495e17c1','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--19',1,'{"question":"A report concludes that every bird species benefits from one feeding method after testing one species. What is the problem?","choices":["A study cannot measure feeding","One bird species represents every species perfectly","The conclusion needs no conditions","The conclusion extends beyond the sampled evidence"],"answer":3,"explanation":""}'::jsonb,'f036788fef8572dfe11c2535c5f6baa0','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--evidence-and-scientific-argument:science--inquiry-environment--evidence-and-scientific-argument--20',1,'{"question":"New reliable results contradict a previous explanation. Which response best reflects argument from evidence?","choices":["Exclude all new results automatically","Reassess the explanation and the new results together","Keep the explanation because it was published first","Treat disagreement as proof that no testing is useful"],"answer":1,"explanation":""}'::jsonb,'b6342971e22cea467641d5c5266ec25e','official',NULL,NULL,'Evidence and Scientific Argument'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--1',1,'{"question":"What is a design criterion?","choices":["A restriction on available resources only","An unmeasured personal prediction","A feature or level of performance a solution should achieve","A required material in every design"],"answer":2,"explanation":""}'::jsonb,'84d9eb0820f885c955b72a66d370de2b','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--2',1,'{"question":"What is a design constraint?","choices":["A limit such as cost, time, materials, or safety requirements","Any measured improvement","A result that must always increase","A scientific law with no practical role"],"answer":0,"explanation":""}'::jsonb,'c6f03a771233cbc905427d35ad25cff4','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--3',1,'{"question":"What is a prototype?","choices":["A guarantee of final success","The complete finished product in every case","A list of unrelated problems","A preliminary version built to test a design"],"answer":3,"explanation":""}'::jsonb,'c6a3c44833c012107d9968204f4b7588','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--4',1,'{"question":"What is iteration in design?","choices":["Building one version without testing","Repeating a test-and-revision cycle","Choosing a solution only by appearance","Replacing all criteria with new units"],"answer":1,"explanation":""}'::jsonb,'4dd4d7234af7eea499898cbefebd0e27','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--5',1,'{"question":"What is a design tradeoff?","choices":["Improving one feature while accepting a disadvantage in another","A situation where every feature improves without limits","A test performed without measurements","A way to avoid all constraints"],"answer":0,"explanation":""}'::jsonb,'f9b11170a0cc31b8d26cbb676d20f8ad','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--6',1,'{"question":"What is optimization?","choices":["Maximizing cost regardless of need","Improving performance within stated criteria and constraints","Removing every requirement","Assuming one design is best in all settings"],"answer":1,"explanation":""}'::jsonb,'7fba8d5ed0302544b94f83db898a8180','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--7',1,'{"question":"What is a failure point in a prototype test?","choices":["A measurement that always supports the design","A reason never to test again","The name of the final product","A part or condition where performance stops meeting requirements"],"answer":3,"explanation":""}'::jsonb,'8f7b864b09868fd4c5aebc4ed24353aa','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--8',1,'{"question":"Why should a problem be defined before choosing materials?","choices":["Materials should be chosen before the intended use is considered","Every design problem has identical material requirements","The intended need and requirements guide useful choices","Available materials determine success without defined criteria"],"answer":2,"explanation":""}'::jsonb,'a97c88d0e813378d54cb6c9d7e87919d','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--9',1,'{"question":"Why compare several possible solutions?","choices":["Different designs may meet requirements with different strengths and weaknesses","Only one solution can ever be imagined","Comparison guarantees no future failures","Every possible design has identical performance"],"answer":0,"explanation":""}'::jsonb,'4d99e48bebfeff71fe81bb26ad0c0e3f','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--10',1,'{"question":"Why should prototypes be tested under relevant conditions?","choices":["Only appearance affects real-world performance","Prototypes cannot be measured","Performance may differ from ideal conditions assumed during planning","Realistic testing removes all need for safety planning"],"answer":2,"explanation":""}'::jsonb,'771d8dc9297f386e3c70f6246318bac3','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--11',1,'{"question":"How can a decision matrix help compare designs?","choices":["It proves all criteria are equally important","It organizes performance against agreed criteria","It replaces evidence with random choices","It guarantees every prototype passes"],"answer":1,"explanation":""}'::jsonb,'207d86bfdfa0e921ad93edf6548fb431','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--12',1,'{"question":"Why can a lightweight bridge design require a strength tradeoff?","choices":["Lower mass always guarantees greater strength","Mass and structure are unrelated to loads","All bridges have identical strength","Reducing material can change load capacity"],"answer":3,"explanation":""}'::jsonb,'1049bf97c655d23b1e60c7828b590467','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--13',1,'{"question":"Why should safety be included in design evaluation?","choices":["Safety matters only after a product fails","Testing eliminates all hazards permanently","Safety can be measured only by product color","A high-performing solution may still create unacceptable risks"],"answer":3,"explanation":""}'::jsonb,'ead1983172302b7e7e932a46357603a2','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--14',1,'{"question":"Why is repeated testing useful when results vary?","choices":["It guarantees all trials become identical","It helps estimate reliability rather than relying on one successful trial","It makes documented methods unnecessary","It allows failed trials to be ignored"],"answer":1,"explanation":""}'::jsonb,'ac35207e05936c7b7a71ab65f3f6f54d','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--15',1,'{"question":"How does engineering design differ in emphasis from scientific explanation?","choices":["Engineering never uses scientific evidence","Science never uses models","Design develops solutions to needs; science investigates explanations of phenomena","Engineering avoids testing"],"answer":2,"explanation":""}'::jsonb,'1280d115fe002010329fb304f2d92f73','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--16',1,'{"question":"A device must fit in a 10 cm space and cost under $20. Which descriptions fit these requirements?","choices":["Constraints on size and cost","Evidence that the prototype already works","Measurements of actual output power","Unrelated experimental results"],"answer":0,"explanation":""}'::jsonb,'77a5ea1100cb0718e5173da7e9feb40e','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--17',1,'{"question":"A filter must remove at least 90% of a test particle type. What is this requirement?","choices":["A publication date","A measurable performance criterion","An uncontrolled variable","A scientific name"],"answer":1,"explanation":""}'::jsonb,'d41d3f49a8796e4613ef4080e9405ab7','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--18',1,'{"question":"Two designs meet strength requirements. One costs $15 and one $25; the budget limit is $20. Which fits the stated conditions?","choices":["The $25 design","Neither design because strength is irrelevant","Both designs regardless of cost","The $15 design"],"answer":3,"explanation":""}'::jsonb,'1c70c4c3ac6e97348378ab1f610beec4','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--19',1,'{"question":"A prototype fails mainly at one joint during loading. What is a useful next step?","choices":["Revise the joint and retest under comparable conditions","Ignore the joint and report only successful trials","Change the load units to make the result look larger","Declare all possible designs impossible"],"answer":0,"explanation":""}'::jsonb,'8ec6598f2a050c40ebf467c036beddfc','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--engineering-design:science--inquiry-environment--engineering-design--20',1,'{"question":"One shelter design is warmer but heavier; another is lighter but colder. What should guide selection?","choices":["Always choose the lighter design without considering warmth","Always choose the warmer design without considering mass","Prioritized criteria, use conditions, and acceptable tradeoffs","Assume all criteria have the same priority in every setting"],"answer":2,"explanation":""}'::jsonb,'568316213a7c76d7a2833bdac6c35357','official',NULL,NULL,'Engineering Design'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--1',1,'{"question":"What is the purpose of a scientific report''s abstract?","choices":["List every raw data value","Replace the complete methods section","Summarize the question, approach, main findings, and conclusion","Present only the author''s biography"],"answer":2,"explanation":""}'::jsonb,'c7627fdfa3b3b6f82ce36e61c3c5c81c','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--2',1,'{"question":"Which section usually explains how data were collected?","choices":["References","Methods","Title","Acknowledgments"],"answer":1,"explanation":""}'::jsonb,'e2f68934038effcd6ef1b63df69d33e6','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--3',1,'{"question":"Which section primarily presents observations and measurements?","choices":["Discussion","References","Acknowledgments","Results"],"answer":3,"explanation":""}'::jsonb,'6c8c8576eec5c68427d773614b8e1b90','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--4',1,'{"question":"Which section commonly interprets findings and their limitations?","choices":["Discussion","Abstract only","Methods only","Results without interpretation"],"answer":0,"explanation":""}'::jsonb,'06552124d84896594e871006f57e0585','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--5',1,'{"question":"What is the purpose of citing a source?","choices":["Credit prior work and help readers locate supporting information","Guarantee the cited claim is correct","Replace all original evidence","Hide the origin of an idea"],"answer":0,"explanation":""}'::jsonb,'32d3e8407fb43a1407de94836cf79392','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--6',1,'{"question":"What is a figure caption?","choices":["A list of all authors'' qualifications","A replacement for the graph''s data","Text explaining a figure''s content, symbols, and relevant conditions","A statement that figures need no units"],"answer":2,"explanation":""}'::jsonb,'a981cfa7b00dfde3ebaaf97122ba4d1d','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--7',1,'{"question":"What is plagiarism?","choices":["Reporting results that challenge an earlier explanation","Using another person''s work or ideas without appropriate acknowledgment","Repeating a published procedure while crediting its source","Using a standard term such as mass or velocity"],"answer":1,"explanation":""}'::jsonb,'cddb9d8fd785ff599643c87d1e3123df','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--8',1,'{"question":"Why should methods describe sampling and measurement procedures?","choices":["Methods should guarantee that all conclusions are correct","Readers do not need to understand comparisons","Procedures are relevant only if results agree","Readers need to evaluate how the evidence was obtained"],"answer":3,"explanation":""}'::jsonb,'2103147e417c71ffc9bd1e6152d410a9','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--9',1,'{"question":"Why should scientific reports distinguish results from interpretations?","choices":["Only interpretations can be numerical","Measurements and explanations play different roles in assessing a claim","Results are always personal opinions","Both sections must contain identical sentences"],"answer":1,"explanation":""}'::jsonb,'aa9e14c55c9240dd138f0defd913ad2e','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--10',1,'{"question":"Why are units and labeled axes necessary in a scientific figure?","choices":["They help readers interpret the represented quantities","They make the sample automatically unbiased","They guarantee a causal relationship","They replace the need to describe data collection"],"answer":0,"explanation":""}'::jsonb,'215c8985744735d3175c89e416cd9611','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--11',1,'{"question":"Why does peer review not guarantee that a paper contains no errors?","choices":["Reviewers never examine methods","Published data cannot be questioned","Review can identify issues but is limited by available evidence and scrutiny","Every paper is tested under every possible condition"],"answer":2,"explanation":""}'::jsonb,'6b0e3d61327ae57bf3c7e08382359372','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--12',1,'{"question":"Why is sharing appropriate data and analysis details useful?","choices":["It guarantees every reanalysis reaches the same result","It eliminates all privacy and consent obligations","It makes interpretation unnecessary","It allows others to inspect and build on the findings"],"answer":3,"explanation":""}'::jsonb,'8a563a1c9477735a332be98b5c89d5f4','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--13',1,'{"question":"Why should limitations be included in a report?","choices":["They clarify the conditions and strength of the conclusions","They prove the entire study has no value","They belong only in unpublished work","They permit researchers to invent missing data"],"answer":0,"explanation":""}'::jsonb,'caa4be259a623e13a4fe680d7f0ab70a','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--14',1,'{"question":"Why must a paraphrase still acknowledge its source?","choices":["Only exact quotations need credit","Paraphrases automatically become experimental data","Citations are needed only for images","Changing wording does not remove the origin of the borrowed idea"],"answer":3,"explanation":""}'::jsonb,'5275425cb8b181ab772d960f49bc9b7d','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--15',1,'{"question":"How should a correction to a published result be communicated?","choices":["Replace data silently without explanation","Clearly identify the change and its effect on the conclusions","Delete all mention of the original methods","Report only that the title changed"],"answer":1,"explanation":""}'::jsonb,'201506e53931532d528a00eb8870e364','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--16',1,'{"question":"A graph shows temperature but its vertical axis is labeled only ''Value.'' What improves communication?","choices":["Remove the numerical scale without adding units","Replace measured values with unlabeled category names","Add the quantity and temperature unit","Use only an author''s name as the axis label"],"answer":2,"explanation":""}'::jsonb,'476d5147ff910799e5992f349672d525','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--17',1,'{"question":"A report says an experiment was repeated but gives no trial count. What information should be added?","choices":["Only the highest recorded result","Only the overall average without the trial count","Only the word repeated without numerical details","The number of trials and relevant procedure details"],"answer":3,"explanation":""}'::jsonb,'6c3330b9c0ec8e2ca93070c3079c648c','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--18',1,'{"question":"A reviewer identifies a possible uncontrolled variable. What is a constructive response?","choices":["Reject the concern because a reviewer disagreed","Hide the relevant methods","Evaluate the concern and clarify, limit, or revise the study as needed","Assume peer review makes new testing unnecessary"],"answer":2,"explanation":""}'::jsonb,'3770f091046dc3c450bb1cd00ca1ff95','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--19',1,'{"question":"A presentation claims a result applies to all students, but only one class was studied. What wording is more defensible?","choices":["Describe the studied class and state limits on generalization","Keep the universal claim without qualification","Claim that every school was sampled","Omit how participants were selected"],"answer":0,"explanation":""}'::jsonb,'dd526b9290a3876e6d3d0c01c690d8c9','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--scientific-communication-and-peer-review:science--inquiry-environment--scientific-communication-and-peer-review--20',1,'{"question":"A student uses another researcher''s graph in a presentation. What is appropriate?","choices":["Remove the author''s name and claim original measurements","Provide attribution and follow any applicable permission or license requirements","Change the colors so attribution is unnecessary","Treat every online graph as unrestricted original work"],"answer":1,"explanation":""}'::jsonb,'d666db6534f521d509c59c9f8ff45806','official',NULL,NULL,'Scientific Communication and Peer Review'),
('original:science--inquiry-environment--sampling-and-field-research:science--inquiry-environment--sampling-and-field-research--1',1,'{"question":"What is a sample in a field study?","choices":["Every organism on Earth","Only the final written conclusion","An instrument used to measure wind","A subset of the population or area being studied"],"answer":3,"explanation":""}'::jsonb,'3b81989ad33fbac8038fd967b1fda956','official',NULL,NULL,'Sampling and Field Research'),
('original:science--inquiry-environment--sampling-and-field-research:science--inquiry-environment--sampling-and-field-research--2',1,'{"question":"What is a quadrat commonly used for?","choices":["Counting all organisms over an entire region at once","Sampling organisms within a defined area","Measuring only the age of each sampled organism","Collecting observations only along a single line"],"answer":1,"explanation":""}'::jsonb,'18be92b08d2ed81a36dbdc1823ca4290','official',NULL,NULL,'Sampling and Field Research'),
