('original:science--inquiry-environment--sampling-and-field-research:science--inquiry-environment--sampling-and-field-research--4',1,'{"question":"What is random sampling intended to reduce?","choices":["Bias from choosing sites based on preference","Natural differences among all organisms","The need for any repeat sampling","All uncertainty in the final population estimate"],"answer":0,"explanation":""}'::jsonb,'b108922b1afaec35f50859e4c2608001','official',NULL,NULL,'Sampling and Field Research'),
