('original:science--inquiry-environment--sampling-and-field-research:science--inquiry-environment--sampling-and-field-research--13',1,'{"question":"Why does a larger representative sample usually improve an estimate?","choices":["It guarantees an exact count of all individuals","It compensates completely for biased site selection","It reduces the influence of chance variation in small samples","It removes the need to record variation"],"answer":2,"explanation":""}'::jsonb,'330dfd95d04e84c5d10842ec3f94b915','official',NULL,NULL,'Sampling and Field Research'),
