('original:science--inquiry-environment--uncertainty-and-measurement-error:science--inquiry-environment--uncertainty-and-measurement-error--2',1,'{"question":"What is a systematic measurement error?","choices":["Random variation with no consistent direction","Only a misspelled unit","An error that shifts results consistently or predictably","Every difference between two organisms"],"answer":2,"explanation":""}'::jsonb,'f63507b3bb55109aadd163db21950eec','official',NULL,NULL,'Uncertainty and Measurement Error'),
