('original:science--earth-space-science--earths-history:science--earth-space-science--earths-history--7',1,'{"question":"What is a mass extinction?","choices":["The death of one individual organism","A geologically rapid loss of many species across the world","A seasonal decrease in one local population","The movement of all species into one habitat"],"answer":1,"explanation":""}'::jsonb,'a2fc8aca23dc044dbf8d25804bb1c7e5','official',NULL,NULL,'Earth''s History'),
('original:science--earth-space-science--earths-history:science--earth-space-science--earths-history--8',1,'{"question":"Why did dense iron-rich material move toward Earth''s center during early differentiation?","choices":["It rose because greater density always produces buoyancy","It remained entirely at the surface because of its mass","It sank relative to less dense material when conditions allowed flow","It mixed uniformly because gravity cannot separate materials"],"answer":2,"explanation":""}'::jsonb,'03ad641f50aace5974458a51bfa978e6','official',NULL,NULL,'Earth''s History'),
('original:science--earth-space-science--earths-history:science--earth-space-science--earths-history--9',1,'{"question":"Why was rising oxygen a major change for early life?","choices":["It immediately created all modern animal groups","It prevented organisms from using energy in cells","It affected only rocks, with no consequences for life","It enabled new metabolic possibilities while harming some oxygen-intolerant organisms"],"answer":3,"explanation":""}'::jsonb,'326049f4c6ff36d70a9b303d77e234fe','official',NULL,NULL,'Earth''s History'),
('original:science--earth-space-science--earths-history:science--earth-space-science--earths-history--10',1,'{"question":"How did an ozone layer affect opportunities for life on land?","choices":["It reduced exposure to harmful ultraviolet radiation","It supplied all the nutrients needed in soil","It caused land to form for the first time","It eliminated the need for water in living cells"],"answer":0,"explanation":""}'::jsonb,'e0afaacb2edcc89553892e4ac03616cf','official',NULL,NULL,'Earth''s History'),
