('original:science--earth-space-science--earths-history:science--earth-space-science--earths-history--13',1,'{"question":"How can a mass extinction affect later evolution?","choices":["All survivors must retain the same ecological roles forever","It makes surviving populations lose all inherited variation","It guarantees immediate return of the extinct species","Surviving groups may diversify into newly available ecological roles"],"answer":3,"explanation":""}'::jsonb,'57b97badfee1573240e63f7dfb63e991','official',NULL,NULL,'Earth''s History'),
('original:science--earth-space-science--earths-history:science--earth-space-science--earths-history--14',1,'{"question":"Why are the earliest parts of Earth''s history harder to reconstruct from surface rocks?","choices":["Many early rocks were altered, destroyed, or recycled","Early Earth rocks formed without minerals","Every early surface remained undisturbed","All surface rocks record the same interval equally well"],"answer":0,"explanation":""}'::jsonb,'be48d95d10c7a6fbc6e9a34bf226eb0e','official',NULL,NULL,'Earth''s History'),
('original:science--earth-space-science--earths-history:science--earth-space-science--earths-history--15',1,'{"question":"How have ice ages affected landscapes?","choices":["Ice ages prevented all erosion","Glaciers eroded and deposited material as ice advanced and retreated","Glaciers made every continent flat","Ice ages changed rock atoms into air"],"answer":1,"explanation":""}'::jsonb,'8f1d38381aabb88bc21f75b2ee585684','official',NULL,NULL,'Earth''s History'),
('original:science--earth-space-science--earths-history:science--earth-space-science--earths-history--16',1,'{"question":"Which sequence places these events from earliest to latest?","choices":["Dinosaurs appear, Earth forms, humans appear, oxygen rises","Humans appear, oxygen rises, Earth forms, dinosaurs appear","Earth forms, atmospheric oxygen rises, dinosaurs appear, humans appear","Oxygen rises, humans appear, dinosaurs appear, Earth forms"],"answer":2,"explanation":""}'::jsonb,'f25b620e73d5d1ad71fb44c77cd0ac6a','official',NULL,NULL,'Earth''s History'),
('original:science--earth-space-science--earths-history:science--earth-space-science--earths-history--17',1,'{"question":"An ancient marine fossil is found in rock now high in a mountain range. What history is supported?","choices":["The ocean must have covered the mountain at its present height","The fossil was made by modern snowfall","The mountain has remained unchanged since Earth''s formation","The material formed in a marine setting and was later uplifted"],"answer":3,"explanation":""}'::jsonb,'4d9d06afc044f55d66374f687a6a264b','official',NULL,NULL,'Earth''s History'),
