('original:science--earth-space-science--earths-history:science--earth-space-science--earths-history--19',1,'{"question":"Two regions now far apart share matching rocks from when Pangaea existed. Which explanation fits plate tectonics?","choices":["Both regions remained fixed while only seawater moved","The regions were once closer and later moved apart","Identical ages alone prove every rock formed in one place","The rocks formed only after the continents reached their current positions"],"answer":1,"explanation":""}'::jsonb,'ea881a6d6df3775732cbc8a36d681b0f','official',NULL,NULL,'Earth''s History'),
('original:science--earth-space-science--earths-history:science--earth-space-science--earths-history--20',1,'{"question":"A boundary layer records abrupt species losses, followed by new groups in younger layers. What pattern does this support?","choices":["No biological change through time","Simultaneous origin of every fossil species","An extinction event followed by diversification","A complete absence of environmental change"],"answer":2,"explanation":""}'::jsonb,'6ac4691155d680a51d4ced496e5324b8','official',NULL,NULL,'Earth''s History'),
