('original:science--earth-space-science--stars-and-stellar-life-cycles:science--earth-space-science--stars-and-stellar-life-cycles--2',1,'{"question":"What process powers a star during its main-sequence stage?","choices":["Chemical combustion of hydrogen with oxygen","Fusion of hydrogen into helium in its core","Nuclear fission of uranium","Gravitational heating as the only continuing source"],"answer":1,"explanation":""}'::jsonb,'eea1f870ce4d0e74395d528b019fb1ef','official',NULL,NULL,'Stars and Stellar Life Cycles'),
('original:science--earth-space-science--stars-and-stellar-life-cycles:science--earth-space-science--stars-and-stellar-life-cycles--3',1,'{"question":"What primarily determines a star''s main-sequence lifetime and later evolution?","choices":["Its distance from Earth","Its apparent position in a constellation","Its initial mass","The number of planets seen nearby"],"answer":2,"explanation":""}'::jsonb,'74135ea4e38565f2e4452f811bf8fe35','official',NULL,NULL,'Stars and Stellar Life Cycles'),
('original:science--earth-space-science--stars-and-stellar-life-cycles:science--earth-space-science--stars-and-stellar-life-cycles--4',1,'{"question":"Which star color generally indicates the highest surface temperature?","choices":["Red","Orange","Yellow","Blue"],"answer":3,"explanation":""}'::jsonb,'e03dabbdde5fa6706ad015795b57f95b','official',NULL,NULL,'Stars and Stellar Life Cycles'),
('original:science--earth-space-science--stars-and-stellar-life-cycles:science--earth-space-science--stars-and-stellar-life-cycles--5',1,'{"question":"What is luminosity?","choices":["A star''s total energy output per unit time","Its brightness only as seen from Earth","Its distance from a telescope","The mass of its planets"],"answer":0,"explanation":""}'::jsonb,'f025705ff26e0d0a43746b020f7e229f','official',NULL,NULL,'Stars and Stellar Life Cycles'),
('original:science--earth-space-science--stars-and-stellar-life-cycles:science--earth-space-science--stars-and-stellar-life-cycles--6',1,'{"question":"What is a white dwarf?","choices":["A cool giant powered by hydrogen fusion in its core","A dense stellar remnant that gradually cools","A gas cloud before a star begins forming","A massive star before its core collapses"],"answer":1,"explanation":""}'::jsonb,'2dd9fb9dc20e808a63c532bd0bd68d87','official',NULL,NULL,'Stars and Stellar Life Cycles'),
('original:science--earth-space-science--stars-and-stellar-life-cycles:science--earth-space-science--stars-and-stellar-life-cycles--7',1,'{"question":"What is a core-collapse supernova?","choices":["The ordinary daily rotation of a star","A planet reflecting sunlight","An explosion associated with collapse of a massive star''s core","The slow cooling of every white dwarf"],"answer":2,"explanation":""}'::jsonb,'e29d3e133ace9ec4f8d627dcc4fe273a','official',NULL,NULL,'Stars and Stellar Life Cycles'),
('original:science--earth-space-science--stars-and-stellar-life-cycles:science--earth-space-science--stars-and-stellar-life-cycles--8',1,'{"question":"Why does a forming protostar heat as it contracts?","choices":["The gas cools because compression always removes internal energy","Its light comes only from nearby stars and no internal heating occurs","Contracting gas loses energy without any rise in temperature","Gravitational energy is converted into thermal energy"],"answer":3,"explanation":""}'::jsonb,'100afed7a194e1e52ba814b0c028507c','official',NULL,NULL,'Stars and Stellar Life Cycles'),
('original:science--earth-space-science--stars-and-stellar-life-cycles:science--earth-space-science--stars-and-stellar-life-cycles--9',1,'{"question":"What supports a main-sequence star against gravitational collapse?","choices":["Outward pressure associated with its hot interior","A solid outer shell holds the hot gas in place","Nearby planets pull the star outward strongly enough to support it","Rotation alone supplies all support in every star"],"answer":0,"explanation":""}'::jsonb,'76b3ef7b7aaee1b95c91e9edc61aa5e8','official',NULL,NULL,'Stars and Stellar Life Cycles'),
('original:science--earth-space-science--stars-and-stellar-life-cycles:science--earth-space-science--stars-and-stellar-life-cycles--10',1,'{"question":"Why do very massive stars generally have shorter main-sequence lifetimes than lower-mass stars?","choices":["They use fuel more slowly despite their higher luminosity","They use their nuclear fuel at much higher rates","They contain no usable hydrogen at birth","They exhaust fuel because distance from Earth is greater"],"answer":1,"explanation":""}'::jsonb,'9e881c68777a9f66d919a5ba51ff2750','official',NULL,NULL,'Stars and Stellar Life Cycles'),
('original:science--earth-space-science--stars-and-stellar-life-cycles:science--earth-space-science--stars-and-stellar-life-cycles--11',1,'{"question":"Why may two equally luminous stars appear different in brightness?","choices":["Luminosity is identical to apparent brightness","The farther one must have less mass","They may be at different distances","Both must have different surface temperatures"],"answer":2,"explanation":""}'::jsonb,'536a1e2fec4b5a62962a12b524612a77','official',NULL,NULL,'Stars and Stellar Life Cycles'),
('original:science--earth-space-science--stars-and-stellar-life-cycles:science--earth-space-science--stars-and-stellar-life-cycles--12',1,'{"question":"What happens when a Sun-like star leaves the main sequence?","choices":["It immediately becomes a black hole regardless of its mass","It remains exactly unchanged because hydrogen depletion has no effect","It turns all of its material into a planet","It expands toward a red-giant stage after core hydrogen is depleted"],"answer":3,"explanation":""}'::jsonb,'e984d54303aa2f7874df96ce8abf5c41','official',NULL,NULL,'Stars and Stellar Life Cycles'),
('original:science--earth-space-science--stars-and-stellar-life-cycles:science--earth-space-science--stars-and-stellar-life-cycles--13',1,'{"question":"What is a planetary nebula in stellar evolution?","choices":["Gas shed by a dying lower-mass star surrounding its remnant","A cloud made only by colliding planets","A new solar system made entirely of planets","The solid surface of a white dwarf"],"answer":0,"explanation":""}'::jsonb,'88c02531b15d76f69661878715c21262','official',NULL,NULL,'Stars and Stellar Life Cycles'),
('original:science--earth-space-science--stars-and-stellar-life-cycles:science--earth-space-science--stars-and-stellar-life-cycles--14',1,'{"question":"Why can supernovae contribute to the chemical enrichment of later star systems?","choices":["They remove every heavy element from space","They eject material containing elements made in stars and explosions","They turn every element into hydrogen only","They prevent future clouds from forming"],"answer":1,"explanation":""}'::jsonb,'b310feae7baf91acffe31abc88f26d8d','official',NULL,NULL,'Stars and Stellar Life Cycles'),
('original:science--earth-space-science--stars-and-stellar-life-cycles:science--earth-space-science--stars-and-stellar-life-cycles--15',1,'{"question":"How is a neutron star different from an ordinary main-sequence star?","choices":["It continues ordinary hydrogen fusion in a large gas envelope","It is less dense than an ordinary main-sequence star","It is a compact remnant rather than a hydrogen-fusing star","It is an expanding shell of gas with no central remnant"],"answer":2,"explanation":""}'::jsonb,'9e2ccac108338bd22cc603b0ca796263','official',NULL,NULL,'Stars and Stellar Life Cycles'),
('original:science--earth-space-science--stars-and-stellar-life-cycles:science--earth-space-science--stars-and-stellar-life-cycles--16',1,'{"question":"A blue star and a red star have similar observed sizes. Which generally has the hotter surface?","choices":["The red star","Both must have exactly equal temperatures","Color gives no information about temperature","The blue star"],"answer":3,"explanation":""}'::jsonb,'28cfd43b50e77f88cd70b6000be645f8','official',NULL,NULL,'Stars and Stellar Life Cycles')
