('original:science--earth-space-science--natural-hazards:science--earth-space-science--natural-hazards--15',1,'{"question":"Why can drought increase wildfire risk in some landscapes?","choices":["Drought increases moisture in dead vegetation","Dry vegetation can ignite and burn more readily","Dry fuels are always less likely to ignite","Fuel moisture has no influence on fire behavior"],"answer":1,"explanation":""}'::jsonb,'86043ac15fceedb95da3966345722991','official',NULL,NULL,'Natural Hazards'),
('original:science--earth-space-science--natural-hazards:science--earth-space-science--natural-hazards--16',1,'{"question":"Two towns face similar flood probability, but one has many homes on the floodplain. Which risk factor is greater there?","choices":["Vulnerability of each building","Magnitude of the river''s flow by definition","Exposure","Probability of the flood by definition"],"answer":2,"explanation":""}'::jsonb,'ff383d8cef8b6f75b9625bfd28ee2024','official',NULL,NULL,'Natural Hazards'),
('original:science--earth-space-science--natural-hazards:science--earth-space-science--natural-hazards--17',1,'{"question":"A building upgrade makes structures better able to withstand expected shaking. Which risk factor is directly reduced?","choices":["Earthquake magnitude","Tectonic plate speed","The depth of every future earthquake","Vulnerability"],"answer":3,"explanation":""}'::jsonb,'067ed229a0786bc2b72fec210bdb2378','official',NULL,NULL,'Natural Hazards'),
('original:science--earth-space-science--natural-hazards:science--earth-space-science--natural-hazards--18',1,'{"question":"A hazard occurs in an uninhabited region with no assets affected. Why may its losses be lower than a smaller event in a city?","choices":["Exposure is much lower","Natural events cannot release energy without people nearby","The smaller city event must have more physical energy","Event size alone determines all losses"],"answer":0,"explanation":""}'::jsonb,'4623f272ead64bc62f15f60abc2d35bd','official',NULL,NULL,'Natural Hazards'),
('original:science--earth-space-science--natural-hazards:science--earth-space-science--natural-hazards--19',1,'{"question":"A warning reaches residents but accessible evacuation routes are absent. What does this show?","choices":["Warnings alone always eliminate structural damage","Warnings need practical response capacity to reduce harm","Evacuation routes have no relation to response options","Only the hazard''s magnitude affects people''s ability to act"],"answer":1,"explanation":""}'::jsonb,'374b238544f1d4ce587fccb0b99ea1ed','official',NULL,NULL,'Natural Hazards'),
('original:science--earth-space-science--natural-hazards:science--earth-space-science--natural-hazards--20',1,'{"question":"Records show floods of varying sizes over many decades. What use of these data is appropriate?","choices":["Name the exact minute of the next flood","Conclude that past floods cannot recur","Estimate patterns and probabilities while acknowledging uncertainty","Assume every future flood will match the largest recorded event"],"answer":2,"explanation":""}'::jsonb,'ed4fb4991e56e4837241658f64deec90','official',NULL,NULL,'Natural Hazards'),
