('original:science--inquiry-environment--waste-and-recycling:science--inquiry-environment--waste-and-recycling--6',1,'{"question":"Which gas can be produced by anaerobic decomposition of organic waste?","choices":["Helium","Methane","Neon","Argon"],"answer":1,"explanation":""}'::jsonb,'af79f2bf6e34690d055a1ddbcd46705e','official',NULL,NULL,'Waste and Recycling'),
