('original:science--inquiry-environment--waste-and-recycling:science--inquiry-environment--waste-and-recycling--8',1,'{"question":"Why is preventing unnecessary waste often prioritized over recycling it?","choices":["Recycling avoids all energy use at every stage","Every discarded material can be recycled indefinitely without losses","Preventing waste always requires more raw material than producing it","It can avoid material and energy use before waste exists"],"answer":3,"explanation":""}'::jsonb,'5d421f72622ace9f8d6674f5250bdfa9','official',NULL,NULL,'Waste and Recycling'),
