('original:science--inquiry-environment--waste-and-recycling:science--inquiry-environment--waste-and-recycling--10',1,'{"question":"Why do accepted recycling materials vary between programs?","choices":["Every recycling symbol guarantees local acceptance","Facilities and markets differ in what they can process","All facilities have identical processing equipment","Local acceptance depends only on package color"],"answer":1,"explanation":""}'::jsonb,'b32bc9ef8ecdc4c5d11ad996cdd78550','official',NULL,NULL,'Waste and Recycling'),
('original:science--inquiry-environment--waste-and-recycling:science--inquiry-environment--waste-and-recycling--11',1,'{"question":"Why can repairing a product reduce resource use?","choices":["It guarantees the item will never wear out again","It removes the need to produce replacement components","It can extend service life and delay replacement","It always changes the item''s material into a recyclable plastic"],"answer":2,"explanation":""}'::jsonb,'cf0543b22c22353a7203a346ec20c103','official',NULL,NULL,'Waste and Recycling'),
('original:science--inquiry-environment--waste-and-recycling:science--inquiry-environment--waste-and-recycling--12',1,'{"question":"Why is e-waste commonly handled through specialized collection?","choices":["All electronics can enter every household recycling stream","Every electronic component safely decomposes in ordinary soil","Electronic waste contains no recoverable materials","It can contain recoverable materials and substances needing controlled handling"],"answer":3,"explanation":""}'::jsonb,'fc3b382fd498fb32377b68b508b318cc','official',NULL,NULL,'Waste and Recycling'),
('original:science--inquiry-environment--waste-and-recycling:science--inquiry-environment--waste-and-recycling--13',1,'{"question":"How is aerobic composting different from anaerobic decay?","choices":["It occurs with oxygen available to decomposers","It prevents any biological activity","It requires no organic material","It only occurs inside metal batteries"],"answer":0,"explanation":""}'::jsonb,'3cffe5d2a880eb81f1adb25afdfe1d50','official',NULL,NULL,'Waste and Recycling'),
