('original:science--inquiry-environment--waste-and-recycling:science--inquiry-environment--waste-and-recycling--18',1,'{"question":"A recycling batch has many items the local facility cannot process. What is a likely consequence?","choices":["Automatic conversion of every item into compost","Extra sorting or rejection of contaminated material","No effect on processing","Creation of new atoms from rejected material"],"answer":1,"explanation":""}'::jsonb,'e8f383e992791171dafe1fab155a956b','official',NULL,NULL,'Waste and Recycling'),
