('original:science--inquiry-environment--renewable-and-nonrenewable-energy:science--inquiry-environment--renewable-and-nonrenewable-energy--8',1,'{"question":"Why are fossil fuels considered nonrenewable?","choices":["They form far more slowly than they are commonly used","They are fully replaced during each annual growing season","They are replenished as quickly as electricity is used","They are called nonrenewable only because they produce heat"],"answer":0,"explanation":""}'::jsonb,'636f04327856c5f05ac95b4a80df7c8c','official',NULL,NULL,'Renewable and Nonrenewable Energy'),
('original:science--inquiry-environment--renewable-and-nonrenewable-energy:science--inquiry-environment--renewable-and-nonrenewable-energy--9',1,'{"question":"Why can electricity storage help with wind and solar generation?","choices":["It guarantees unlimited output from a generator","It can shift delivery from times of production to times of demand","It raises conversion efficiency to exactly 100%","It prevents every difference between generation and demand"],"answer":1,"explanation":""}'::jsonb,'2e9f61ce2c854348d173bba6513446db','official',NULL,NULL,'Renewable and Nonrenewable Energy'),
