('original:science--inquiry-environment--renewable-and-nonrenewable-energy:science--inquiry-environment--renewable-and-nonrenewable-energy--11',1,'{"question":"What is a potential ecological tradeoff of a large hydroelectric dam?","choices":["It always improves migration for every fish species","It leaves river sediment transport unchanged","It cannot affect habitats upstream","It can alter river flow and aquatic habitats"],"answer":3,"explanation":""}'::jsonb,'fa74e1d73551701f5278606ad83f6f12','official',NULL,NULL,'Renewable and Nonrenewable Energy'),
('original:science--inquiry-environment--renewable-and-nonrenewable-energy:science--inquiry-environment--renewable-and-nonrenewable-energy--12',1,'{"question":"Why can biomass be depleted despite being called renewable?","choices":["Use can exceed regrowth or replenishment","Biomass cannot be replenished through plant growth","Burning biomass always causes regrowth at the same rate","Calling a source renewable guarantees sustainable use"],"answer":0,"explanation":""}'::jsonb,'d0525b0d84ba10c71c025a8460929b0d','official',NULL,NULL,'Renewable and Nonrenewable Energy'),
('original:science--inquiry-environment--renewable-and-nonrenewable-energy:science--inquiry-environment--renewable-and-nonrenewable-energy--13',1,'{"question":"How can energy conservation reduce resource demand?","choices":["It increases the amount of fuel needed for identical unnecessary use","Using less energy for unnecessary activities lowers required supply","It makes all generating resources unlimited","It only changes electricity prices, never consumption"],"answer":1,"explanation":""}'::jsonb,'082861d3519762840d643385f3f7ad0c','official',NULL,NULL,'Renewable and Nonrenewable Energy'),
('original:science--inquiry-environment--renewable-and-nonrenewable-energy:science--inquiry-environment--renewable-and-nonrenewable-energy--14',1,'{"question":"Why are local conditions important when choosing renewable energy projects?","choices":["Every location has the same renewable potential","A project''s size is the only factor that affects suitability","Sunlight, wind, water, geology, and ecological constraints vary","Ecological constraints matter only for fossil fuels"],"answer":2,"explanation":""}'::jsonb,'7d212a832ee9f63978ed6591c8a0dc5d','official',NULL,NULL,'Renewable and Nonrenewable Energy'),
('original:science--inquiry-environment--renewable-and-nonrenewable-energy:science--inquiry-environment--renewable-and-nonrenewable-energy--15',1,'{"question":"How does energy efficiency differ from simply reducing a service?","choices":["Efficiency means stopping every activity","Efficiency creates energy from nothing","Efficiency describes only fuel price","Efficiency provides a similar service with less energy"],"answer":3,"explanation":""}'::jsonb,'875ab169de8b374d341cfc1e60ccbee2','official',NULL,NULL,'Renewable and Nonrenewable Energy'),
('original:science--inquiry-environment--renewable-and-nonrenewable-energy:science--inquiry-environment--renewable-and-nonrenewable-energy--16',1,'{"question":"A region has steady winds but few usable rivers. Which resource is most directly supported by these conditions?","choices":["Wind generation","Large river hydropower","Coal formation each season","New uranium created by the wind"],"answer":0,"explanation":""}'::jsonb,'cac05106eb228bb4087bd73bce0d3421','official',NULL,NULL,'Renewable and Nonrenewable Energy')
