('original:science--inquiry-environment--renewable-and-nonrenewable-energy:science--inquiry-environment--renewable-and-nonrenewable-energy--18',1,'{"question":"A solar system produces more electricity at midday than users need. Which measure can help meet evening demand?","choices":["Operate the panels unchanged without light","Discard output that is not used immediately","Store some midday energy for later use","Assume evening demand will always be zero"],"answer":2,"explanation":""}'::jsonb,'1237244afafbdb415872e609ea627a8c','official',NULL,NULL,'Renewable and Nonrenewable Energy'),
