('original:science--inquiry-environment--human-population-and-resource-use:science--inquiry-environment--human-population-and-resource-use--2',1,'{"question":"What does per-capita resource use mean?","choices":["Resource use per continent regardless of population","The total amount of resource left underground","The maximum amount any one factory can use","Resource use per person"],"answer":3,"explanation":""}'::jsonb,'98c4d09f1be756a10f8e089307a319de','official',NULL,NULL,'Human Population and Resource Use'),
('original:science--inquiry-environment--human-population-and-resource-use:science--inquiry-environment--human-population-and-resource-use--3',1,'{"question":"Which change adds people to a region''s population without a birth?","choices":["Immigration","Emigration","Mortality","A decline in birth rate"],"answer":0,"explanation":""}'::jsonb,'a0710725c24851cdfb1a3d9bdb211f65','official',NULL,NULL,'Human Population and Resource Use'),
