('original:science--inquiry-environment--human-population-and-resource-use:science--inquiry-environment--human-population-and-resource-use--9',1,'{"question":"How can technology change resource demand?","choices":["It always reduces every impact regardless of how it is used","It leaves every material requirement unchanged","It can change efficiency and which materials are required","It prevents consumption from rising with expanded activity"],"answer":2,"explanation":""}'::jsonb,'a52a83b499bdef7c4a99d85a97aca5ee','official',NULL,NULL,'Human Population and Resource Use'),
('original:science--inquiry-environment--human-population-and-resource-use:science--inquiry-environment--human-population-and-resource-use--10',1,'{"question":"Why can carrying capacity change over time?","choices":["It is defined by one fixed global number","People never alter resource systems","Only births can affect resources","Resources, technology, and environmental conditions can change"],"answer":3,"explanation":""}'::jsonb,'f65f96d6b01b308094e2a3b077f0a3a4','official',NULL,NULL,'Human Population and Resource Use'),
('original:science--inquiry-environment--human-population-and-resource-use:science--inquiry-environment--human-population-and-resource-use--11',1,'{"question":"Why can improved efficiency fail to reduce total consumption as much as expected?","choices":["Expanded use can offset some savings","Per-use savings always guarantee the same total reduction","Efficient devices cannot be operated more often","Efficiency changes resource supply but never demand"],"answer":0,"explanation":""}'::jsonb,'20dc1d78720ad8951209c7fb31d08b42','official',NULL,NULL,'Human Population and Resource Use'),
('original:science--inquiry-environment--human-population-and-resource-use:science--inquiry-environment--human-population-and-resource-use--12',1,'{"question":"How can dense development reduce some per-person infrastructure needs?","choices":["Density necessarily eliminates all environmental impacts","Shared services and shorter travel can lower certain inputs","All travel and water use become zero","Sharing infrastructure always raises per-person material use"],"answer":1,"explanation":""}'::jsonb,'a51459ba9eca23b2bb0ef3f0dd6a7fcd','official',NULL,NULL,'Human Population and Resource Use'),
('original:science--inquiry-environment--human-population-and-resource-use:science--inquiry-environment--human-population-and-resource-use--13',1,'{"question":"Why are population projections usually reported with assumptions?","choices":["Birth and death rates are permanently fixed everywhere","A projection gives an exact count regardless of migration","Future births, deaths, and migration are uncertain","Assumptions guarantee that only one outcome is possible"],"answer":2,"explanation":""}'::jsonb,'b588e4ed8b1ef69a797ff381ff15b918','official',NULL,NULL,'Human Population and Resource Use'),
('original:science--inquiry-environment--human-population-and-resource-use:science--inquiry-environment--human-population-and-resource-use--14',1,'{"question":"Why can equal total water use hide different pressures on supply?","choices":["Water is replenished at identical rates in all places","Equal use always means equal scarcity","Water availability depends only on population size","Local water availability and replenishment can differ"],"answer":3,"explanation":""}'::jsonb,'ca3a7a50b828da607e754998d6ae74cd','official',NULL,NULL,'Human Population and Resource Use'),
('original:science--inquiry-environment--human-population-and-resource-use:science--inquiry-environment--human-population-and-resource-use--15',1,'{"question":"How does renewable-resource stock differ from its replacement rate?","choices":["Stock is an amount available; rate is replenishment per unit time","Both are amounts stored at one moment","The rate is the total amount currently available","The stock is the amount entering per unit time"],"answer":0,"explanation":""}'::jsonb,'7a9c830238423155d4247eccf679729d','official',NULL,NULL,'Human Population and Resource Use'),
('original:science--inquiry-environment--human-population-and-resource-use:science--inquiry-environment--human-population-and-resource-use--16',1,'{"question":"A town has 1,000 people using 100 L each per day. What is total daily use?","choices":["1,100 L","100,000 L","10,000 L","100 L"],"answer":1,"explanation":""}'::jsonb,'1f6ca1ed4568f9e69978c48514f38b91','official',NULL,NULL,'Human Population and Resource Use'),
('original:science--inquiry-environment--human-population-and-resource-use:science--inquiry-environment--human-population-and-resource-use--17',1,'{"question":"One town has twice as many residents but half the per-person energy use of another. How do their total uses compare?","choices":["The larger town uses twice as much","The larger town uses half as much","They are equal","The larger town uses four times as much"],"answer":2,"explanation":""}'::jsonb,'eea6871722a8ae469ffeaa4b7022dbea','official',NULL,NULL,'Human Population and Resource Use'),
('original:science--inquiry-environment--human-population-and-resource-use:science--inquiry-environment--human-population-and-resource-use--18',1,'{"question":"A population starts at 10,000, with 200 births, 100 deaths, 50 immigrants, and 150 emigrants in a year. What is its final size?","choices":["10,200","9,800","10,500","10,000"],"answer":3,"explanation":""}'::jsonb,'6ba89ed857cc89c45b72e53ab2da859f','official',NULL,NULL,'Human Population and Resource Use'),
('original:science--inquiry-environment--human-population-and-resource-use:science--inquiry-environment--human-population-and-resource-use--19',1,'{"question":"A reservoir receives 80 units of water per day while 100 units are withdrawn, with other flows negligible. What is the daily storage change?","choices":["A decrease of 20 units","An increase of 20 units","A decrease of 180 units","No change"],"answer":0,"explanation":""}'::jsonb,'445455b4efa30ad86b8b12f4c21d499c','official',NULL,NULL,'Human Population and Resource Use'),
('original:science--inquiry-environment--human-population-and-resource-use:science--inquiry-environment--human-population-and-resource-use--20',1,'{"question":"A report predicts future resource use from constant per-person consumption. What important follow-up should be considered?","choices":["Assume per-person consumption can never change","Whether per-person consumption may change","Use population totals without considering any consumption rate","Treat all future resources as unlimited"],"answer":1,"explanation":""}'::jsonb,'9303d45b02f4e5ee131e430194e70c8b','official',NULL,NULL,'Human Population and Resource Use'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--1',1,'{"question":"What is an edge effect in a habitat?","choices":["A change found equally throughout every habitat","A process that occurs only at the center of a forest","A guarantee that all boundary areas support identical species","A difference in conditions near a habitat boundary compared with its interior"],"answer":3,"explanation":""}'::jsonb,'26c1f5c8fb3ff8cde5a071eea60531e8','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--2',1,'{"question":"What is a wildlife corridor?","choices":["A connection that can allow organisms to move between habitat patches","A wall that prevents all animal movement","A site designed only for waste disposal","A road with no ecological function"],"answer":0,"explanation":""}'::jsonb,'caf277d38b8e5bbad2b8484f317bd709','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--3',1,'{"question":"What is ecological restoration?","choices":["Replacing diverse communities with one uniform crop","Assisting recovery of a degraded ecosystem","Keeping every species at an unchanging number forever","Moving degraded material elsewhere without assisting recovery"],"answer":1,"explanation":""}'::jsonb,'e71a871048f2e59f35b1e47f7c84b709','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--4',1,'{"question":"What is a reference ecosystem used for in restoration?","choices":["A guarantee that all restored sites become identical","A replacement for measuring the restored site''s progress","A comparison that helps define recovery goals","A rule that local conditions can be ignored"],"answer":2,"explanation":""}'::jsonb,'83e55d77e2516475bab776428bca6d00','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--5',1,'{"question":"What is an invasive species?","choices":["Every nonnative species regardless of effects","Every native species with rapid growth","Any organism moving between two habitat patches","A nonnative species whose establishment causes or is likely to cause harm"],"answer":3,"explanation":""}'::jsonb,'fe4075b303bb2eaaa9fc217d9a9773a1','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--6',1,'{"question":"What is a riparian zone?","choices":["Land alongside a river or stream","The open water at the center of a lake","The deep ocean floor below coastal water","Land defined only by permanent desert conditions"],"answer":0,"explanation":""}'::jsonb,'9841e47d0d3c1283522b2546f34c85a2','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--7',1,'{"question":"What is ecological succession?","choices":["Movement of one animal for one afternoon","Change in community composition over time","Permanent stability of every species","The loss of every nutrient from soil"],"answer":1,"explanation":""}'::jsonb,'e62be19fc1e23eb303a7d5936ec82850','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--8',1,'{"question":"Why can fragmentation reduce gene flow between populations?","choices":["Patch separation always increases movement between them","Gene flow does not depend on movement or reproduction","Separated patches can limit movement and mating","Every patch necessarily keeps the same allele frequencies forever"],"answer":2,"explanation":""}'::jsonb,'d28df3022c84ebc60f67d78efb95944f','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--9',1,'{"question":"How can restoring native plants benefit some local animals?","choices":["Every native plant supports every animal equally","Native plants never compete for soil resources","Native plants eliminate all disease in local animals","They can supply suitable food and habitat relationships"],"answer":3,"explanation":""}'::jsonb,'d056779d4e8fbe6cb847254487d8b63a','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--10',1,'{"question":"Why is removing a stressor often important before planting for restoration?","choices":["Ongoing disturbance can prevent newly planted communities from establishing","Planting guarantees recovery despite unchanged disturbance","Removing a stressor replaces the need to set any goal","Stressors affect only mature plants and never seedlings"],"answer":0,"explanation":""}'::jsonb,'2f49dcfbc4efccdfe95fe81e14a39719','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--11',1,'{"question":"How can vegetation along a stream reduce sediment entering the water?","choices":["Roots guarantee that no sediment moves during any flood","Roots stabilize soil and vegetation slows runoff","Vegetation increases erosion in every soil condition","Plants stop rainfall before it reaches the stream"],"answer":1,"explanation":""}'::jsonb,'b190aacdbd1528ec3f95b7616797068e','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--12',1,'{"question":"Why monitor a restored site over several years?","choices":["One photograph proves permanent recovery","Recovery has no time-dependent changes","Recovery and unintended effects can change over time","Monitoring alone guarantees every goal is reached"],"answer":2,"explanation":""}'::jsonb,'5019dbe1ee49ca3b3a631b08b8a6dbfe','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--13',1,'{"question":"Why may reintroducing a species fail if habitat conditions remain unsuitable?","choices":["Reintroduction removes every food and shelter requirement","All species tolerate any temperature and water conditions","A released population survives regardless of habitat quality","The original limits on survival may still exist"],"answer":3,"explanation":""}'::jsonb,'a2b98e1d60dfcaa31af9c6be18f5c521','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--14',1,'{"question":"How can a wildlife crossing help where a road divides habitat?","choices":["It can reduce barriers and dangerous crossings","It guarantees that no animal is ever harmed by traffic","It prevents every form of habitat fragmentation","It makes all species use exactly the same route"],"answer":0,"explanation":""}'::jsonb,'91a2431381f723ae034ef2d9469f8590','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--15',1,'{"question":"Why can restoration involve tradeoffs rather than one perfect outcome?","choices":["Every ecosystem has identical recovery needs","Goals, species needs, resources, and site conditions can conflict","All goals can always be met with no resource limits","Only one species uses any habitat"],"answer":1,"explanation":""}'::jsonb,'d1ce75d8713dadf2229c46ac17f181f9','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--16',1,'{"question":"After wetland drainage, a project restores more natural water flow. Which restoration element is directly addressed?","choices":["Atomic number","Stellar brightness","Hydrology","Magnetic polarity"],"answer":2,"explanation":""}'::jsonb,'32a96487774a2bdc553375487af46f45','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--17',1,'{"question":"A restored site has more plants but only one species. Which measurement would add useful information about recovery?","choices":["Only the total number of plants, counted again","Only the cost of the original planting","Only the project''s area without any ecological observations","Native species diversity and community structure"],"answer":3,"explanation":""}'::jsonb,'3c32965f0b73221b684b6098ac90c157','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--18',1,'{"question":"Two habitat patches reconnect, and individuals move between them. Which outcome becomes more possible?","choices":["Gene flow between the populations","Immediate elimination of all variation","Permanent isolation of both populations","Complete prevention of reproduction"],"answer":0,"explanation":""}'::jsonb,'bbe5bc8a134025e36b052d7baf207474','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--19',1,'{"question":"A restoration treatment increases plant survival, but an untreated comparison also improves equally. What conclusion is warranted?","choices":["The treatment alone must explain both improvements","The data do not isolate a benefit of the treatment","The comparison site has no scientific value","All monitoring should stop immediately"],"answer":1,"explanation":""}'::jsonb,'8adbb04204c20ea35a395d121155b5ac','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--habitat-change-and-restoration:science--inquiry-environment--habitat-change-and-restoration--20',1,'{"question":"An invasive plant returns after initial removal. What does this suggest for management?","choices":["One removal guarantees permanent control","The returning plant automatically becomes native","Follow-up monitoring and repeated control may be needed","Recovery cannot be measured after any species returns"],"answer":2,"explanation":""}'::jsonb,'a09fb8c45e01d9b0012c1209f8067410','official',NULL,NULL,'Habitat Change and Restoration'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--1',1,'{"question":"What is a system boundary?","choices":["A defined separation between a system and its surroundings","A guarantee that the system exchanges nothing","A line that must follow a national border","A physical wall required around every system"],"answer":0,"explanation":""}'::jsonb,'1c6a70e146682c81cec20ea6f1738ae5','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--2',1,'{"question":"What is an input to an environmental system?","choices":["Material or energy leaving it","Material or energy entering the chosen system","The total amount already stored only","A process that cannot be measured"],"answer":1,"explanation":""}'::jsonb,'b72b09978dcc349f719ac4ca6df161a0','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--3',1,'{"question":"What is a system stock?","choices":["Only the speed of material movement","A one-time label for a species","An amount accumulated within a system","The number of possible models"],"answer":2,"explanation":""}'::jsonb,'32aa150ae58ff79ad6825c49ec2db939','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--4',1,'{"question":"What is a positive feedback?","choices":["Any change that improves an outcome for people","A process that opposes the initial disturbance","A process with no influence on later conditions","A process that amplifies an initial change"],"answer":3,"explanation":""}'::jsonb,'d79de2f3987070e3454eb0593eaaca1f','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--5',1,'{"question":"What is a negative feedback?","choices":["A process that opposes an initial change","Any change that produces an undesirable outcome","A process that amplifies the initial disturbance","A transfer that changes no other process"],"answer":0,"explanation":""}'::jsonb,'2a6eae389dacbbdcd8370fc88a5351b6','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--6',1,'{"question":"What is a time lag in a system response?","choices":["The maximum possible size of a response","A delay between a cause and an observable effect","A response occurring before its cause","A difference only in the units used"],"answer":1,"explanation":""}'::jsonb,'16237898ad08f5e2e3dc86bc13d1d079','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--7',1,'{"question":"What is dynamic equilibrium in a reservoir''s material balance?","choices":["All transfers permanently stop","Inputs rise while outputs remain zero","Inputs and outputs balance while transfers continue","Every stored particle is motionless"],"answer":2,"explanation":""}'::jsonb,'825cc51d88436f379340a9399d4ac8d3','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--8',1,'{"question":"Why does a positive feedback not mean a desirable outcome?","choices":["Positive means all organisms benefit equally","Feedback signs are based only on opinions","Amplification always removes every risk","Positive describes amplification, not value or benefit"],"answer":3,"explanation":""}'::jsonb,'1e93eb473a1e6a8fca233393ff781ba8','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--9',1,'{"question":"How can loss of reflective snow contribute to further warming?","choices":["Darker surfaces absorb more sunlight, encouraging more snow loss","Darker surfaces reflect more sunlight than snow","Snow loss leaves energy absorption unchanged","Melting always increases surface reflectivity"],"answer":0,"explanation":""}'::jsonb,'6425041c1f57a467d7a2c4dbe09a3687','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--10',1,'{"question":"How can increased plant uptake of carbon dioxide oppose an initial rise in carbon dioxide under suitable conditions?","choices":["It increases carbon dioxide while opposing the rise","It removes some of the added carbon dioxide","It guarantees carbon dioxide reaches zero","It stops carbon from moving through organisms"],"answer":1,"explanation":""}'::jsonb,'aec1289db9b1c05604197ee7d23b75c7','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--11',1,'{"question":"Why can a system appear stable while large flows continue?","choices":["A steady stock proves inputs and outputs are zero","All environmental systems exchange no energy","Balanced inputs and outputs can maintain a steady stock","Any material flow must increase the stock"],"answer":2,"explanation":""}'::jsonb,'c4b98d7f0e47c7b4b1f9ac8c4ee66e0e','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--12',1,'{"question":"Why can a delayed response complicate management?","choices":["Effects occur only while an action is still taking place","Delayed effects can be ignored when choosing actions","Time lags guarantee there is no causal relationship","Present actions may have effects not visible immediately"],"answer":3,"explanation":""}'::jsonb,'8c74f5522f5dedfaee40f0351ad84f24','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--13',1,'{"question":"What is an environmental threshold?","choices":["A condition beyond which a system''s behavior can change substantially","A maximum instrument reading unrelated to system behavior","A condition that is identical in all ecosystems","A point beyond which measurement is impossible"],"answer":0,"explanation":""}'::jsonb,'bbde7a58e4ebbf79b02cea95c288648f','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--14',1,'{"question":"Why are feedbacks important in environmental models?","choices":["They guarantee that models have no uncertainty","They connect changes to processes that modify later changes","They replace the need for observational evidence","They ensure every response is proportional and immediate"],"answer":1,"explanation":""}'::jsonb,'40711a5e960aa47160b80c11cb04b212','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--15',1,'{"question":"Why can changing a system boundary change an assessment?","choices":["It changes conservation of matter within the same process","It makes excluded effects cease to exist physically","It changes which transfers and effects are counted","It guarantees that a narrower boundary captures more effects"],"answer":2,"explanation":""}'::jsonb,'1597e0aa47119a7148acb09bd55b0911','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--16',1,'{"question":"A pond receives 50 L per minute and loses 30 L per minute, with other flows negligible. What is its storage change?","choices":["A decrease of 20 L per minute","An increase of 80 L per minute","No change","An increase of 20 L per minute"],"answer":3,"explanation":""}'::jsonb,'d1f57b8d2106ff15ae9ec52ab7e3025a','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--17',1,'{"question":"Higher temperature causes more ice melt, and the resulting darker surface increases warming. What feedback is described?","choices":["Positive feedback","Negative feedback","No feedback","A permanently closed material cycle"],"answer":0,"explanation":""}'::jsonb,'8837ca59160a6af45e28911fb8de894d','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--18',1,'{"question":"A population grows, increasing competition that lowers its growth rate. What feedback is described?","choices":["Positive feedback","Negative feedback","No interaction between population and resources","A process making resource supply unlimited"],"answer":1,"explanation":""}'::jsonb,'2bbe3831946eefad27acef538ac6c4e1','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--19',1,'{"question":"A lake''s pollutant input falls, but sediments continue releasing old pollution. What helps explain delayed improvement?","choices":["All pollution vanishes as soon as inputs decline","Stored pollution can never reenter the water","Stored material and time lags","The decline proves there are no continuing internal flows"],"answer":2,"explanation":""}'::jsonb,'1dd78d7322fe780b67be544dad63af01','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--inquiry-environment--environmental-systems-and-feedbacks:science--inquiry-environment--environmental-systems-and-feedbacks--20',1,'{"question":"A model counts emissions during product use but excludes manufacturing. How should its result be interpreted?","choices":["It necessarily represents all life-cycle stages","It proves manufacturing has no impacts","It can be compared directly with any differently bounded study","It describes the chosen boundary, not the full product life cycle"],"answer":3,"explanation":""}'::jsonb,'389d402212ce974c4eb97a9c94d8fe75','official',NULL,NULL,'Environmental Systems and Feedbacks'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--1',1,'{"question":"A team is designing a low-cost water filter for a school demonstration. Which statement is a design criterion?","choices":["The filter must reduce visible sediment by at least 80%","The team has two class periods to build it","The team has $15 to spend","Only materials in the classroom may be used"],"answer":0,"explanation":""}'::jsonb,'7585010052a9f6c23a02b379d184c142','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--2',1,'{"question":"A design constraint differs from a criterion because a constraint","choices":["describes a feature that makes the solution successful","sets a limit the design must work within","is the final test result","is a drawing of the prototype"],"answer":1,"explanation":""}'::jsonb,'3cb7bfcea489ef5c86111dabca808cd2','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--3',1,'{"question":"Why do engineers build a prototype before producing a final device?","choices":["To avoid needing to test the design","To prove the first idea is always correct","To examine how a design works and find changes to make","To remove all constraints from the problem"],"answer":2,"explanation":""}'::jsonb,'188d0990e99cc69842d96a7b197d83e6','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--4',1,'{"question":"Two bridge models use the same materials. One holds more mass but takes longer to assemble. What does this comparison illustrate?","choices":["A controlled variable that should be ignored","A result that proves one model is unsafe","A criterion that cannot be measured","A trade-off between performance and assembly time"],"answer":3,"explanation":""}'::jsonb,'05d264bc539457d290fe8b713c93f384','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--5',1,'{"question":"A group changes the wing shape and also changes the launch angle between trials. What is the main problem?","choices":["The test does not isolate the effect of wing shape","The model uses too few materials","The group has already optimized its design","The launch angle is a dependent variable"],"answer":0,"explanation":""}'::jsonb,'9409ebe84b3afa531e3d1a298cd367c4','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--6',1,'{"question":"A prototype repeatedly tips over when a load is placed near one edge. Which revision is most directly supported by this evidence?","choices":["Add decoration to the upper frame","Make the base wider or lower the center of mass","Increase the load during every later trial","Remove the measurement scale"],"answer":1,"explanation":""}'::jsonb,'71852368fa1e7c0c38a099e98193c533','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--7',1,'{"question":"Which sequence best represents an iterative engineering process?","choices":["Build once, present, then avoid changes","Choose materials, advertise, and skip evaluation","Define a need, design, build, test, and revise","Test a final product before identifying criteria"],"answer":2,"explanation":""}'::jsonb,'be783e1ee2be608841bf761adf448709','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--8',1,'{"question":"A team tests three insulation materials around identical cups of warm water. Which variable should be kept constant for a fair comparison?","choices":["The temperature change measured after ten minutes","The insulation material around each cup","The conclusion the team hopes to reach","The type of thermometer used in every cup"],"answer":3,"explanation":""}'::jsonb,'b7dead64831f2ae4b49a96a166b606e7','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--9',1,'{"question":"A water-rocket team wants to compare how fin area affects flight distance. Which design best tests that question?","choices":["Change fin area while holding launch pressure and rocket mass as constant as possible","Change fin area, pressure, and mass together","Use a different launch surface for each fin size","Measure only the longest flight and discard the rest"],"answer":0,"explanation":""}'::jsonb,'cc954f9fd19af7159cfd508730b87efa','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--10',1,'{"question":"A team''s first solar oven reaches 48°C, below its 60°C target. What is the best next step?","choices":["Claim that the oven meets the criterion because it became warm","Record the result, inspect heat-loss paths, and test a targeted revision","Change several features and skip another measurement","Replace the target with the measured result"],"answer":1,"explanation":""}'::jsonb,'92e6b02d9673256c34d0f2c56a6ba4f1','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--11',1,'{"question":"What is the primary purpose of a project specification?","choices":["To guarantee the prototype will work on the first attempt","To replace all testing with a written plan","To list the problem, measurable success criteria, and important constraints","To record only the names of team members"],"answer":2,"explanation":""}'::jsonb,'7dd56b4fd83397b80c0e5281c5655b7e','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--12',1,'{"question":"A team has limited battery capacity and must choose between a faster motor and a longer operating time. This is best described as","choices":["a random error in measurement","a failure to define the problem","a controlled experiment with no variables","a trade-off between competing design goals"],"answer":3,"explanation":""}'::jsonb,'ff8bb5e6f0c3678fca034584f14b4867','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--13',1,'{"question":"A ramp design moves a cart farther, but it also makes the cart harder to stop safely. Which action shows responsible design reasoning?","choices":["Compare both performance goals and test a safe stopping feature","Keep the longer ramp because distance is the only useful criterion","Remove the stopping test because it complicates the project","Change the safety criterion after each trial"],"answer":0,"explanation":""}'::jsonb,'e04d15bab4f86b0cb7c81a17a5eb5b8e','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--14',1,'{"question":"Why should a team repeat a prototype test several times?","choices":["One test always identifies every source of error","Repeated tests help reveal variability and make comparisons more dependable","Repeated tests guarantee the design meets all criteria","More tests make measurement methods unnecessary"],"answer":1,"explanation":""}'::jsonb,'2f20043839dc5799477a92f5a9729ae5','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--15',1,'{"question":"A sensor''s readings jump between 18 and 19 units when the environment is steady. What is a sensible first response?","choices":["Assume the largest reading is the true value","Delete every reading that differs from the expected result","Check the sensor setup and collect repeated readings before changing the design","Replace the sensor with an unrelated actuator"],"answer":2,"explanation":""}'::jsonb,'2118ec30e649ef08a3f717e07c31deab','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--16',1,'{"question":"Which change would most likely improve the reliability of a small wind-turbine test?","choices":["Move the fan closer whenever a turbine performs poorly","Change both blade shape and generator between trials","Record only whether the turbine spins","Use the same fan distance and speed for each blade design"],"answer":3,"explanation":""}'::jsonb,'533a90b0680949326f9fbb0a68ca4168','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--17',1,'{"question":"A team selects a material because it is strong, lightweight, and recyclable, but it exceeds the budget. Which decision best addresses the full design problem?","choices":["Compare alternative materials against all criteria and the cost constraint","Ignore cost because strength is measurable","Remove recyclability from the results without review","Choose the strongest material automatically"],"answer":0,"explanation":""}'::jsonb,'2a82cb989b4262d42833ec11421f71e3','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--18',1,'{"question":"An engineer uses a scale model of a flood barrier. Why should the team be cautious when applying model results to a full-size river?","choices":["Scale models cannot represent any real structure","Some forces and conditions may not scale proportionally","A smaller model has no measurable variables","The full-size barrier will have identical water flow by definition"],"answer":1,"explanation":""}'::jsonb,'19e0a17430e392351fd20e6c01d55c34','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--19',1,'{"question":"Which evidence would best support the claim that a redesigned package protects its contents better?","choices":["A drawing showing the new package is larger","A statement that the team prefers the new color","Repeated drop-test damage scores for the old and new designs under the same conditions","One successful drop of the redesigned package"],"answer":2,"explanation":""}'::jsonb,'12f9094d86157654f8fb321b9b34bc68','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--stem-challenges-and-projects:science--engineering-stem--stem-challenges-and-projects--20',1,'{"question":"A project works in a classroom trial but fails outdoors in cold weather. What should the team do next?","choices":["Conclude the device cannot be improved","Report only the classroom result as universal evidence","Remove temperature from the design requirements","Revise the test conditions to include realistic temperature ranges and evaluate changes"],"answer":3,"explanation":""}'::jsonb,'5214b7e55450a155004588ba75fafdf3','official',NULL,NULL,'STEM Challenges and Projects'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--1',1,'{"question":"In a robot, which component detects distance from a nearby obstacle?","choices":["A sensor","An actuator","A gear train","A chassis"],"answer":0,"explanation":""}'::jsonb,'7f58022e8159dcfe983b1a7ea1f70a39','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--2',1,'{"question":"What is an algorithm?","choices":["A device that converts electricity to motion","A sequence of steps for solving a problem","A measurement that cannot be repeated","A type of robot battery"],"answer":1,"explanation":""}'::jsonb,'6ed6f5064106e546685702961dc0edb6','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--3',1,'{"question":"A program repeats a movement sequence four times. Which programming structure is most appropriate?","choices":["Variable","Comment","Loop","Sensor"],"answer":2,"explanation":""}'::jsonb,'ae8f8eabaf74d3258b9b4c382ad33728','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--4',1,'{"question":"A robot turns left only when its distance sensor detects an obstacle within 10 centimeters. This behavior uses","choices":["a fixed sequence with no input","a comment instead of an instruction","an actuator as a measurement","a conditional decision"],"answer":3,"explanation":""}'::jsonb,'2299206824a520e5b79c7726098a11d0','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--5',1,'{"question":"Which part of a robot produces motion in response to a control signal?","choices":["Actuator","Sensor","Algorithm","Input value"],"answer":0,"explanation":""}'::jsonb,'f0977b0a3e88cbaccc15882c2c065636','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--6',1,'{"question":"A line-following robot drifts off the track, corrects itself, and then drifts again. Which improvement most directly supports stable control?","choices":["Disable the sensors and increase the maximum speed","Use sensor feedback to make smaller, timely motor adjustments","Repeat the same full-speed turn on every surface","Remove the control loop"],"answer":1,"explanation":""}'::jsonb,'758299bc0f6b1e5f6459d898f4164de1','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--7',1,'{"question":"A robot''s sensor returns 6 centimeters, but the program treats every value below 8 centimeters as an obstacle. What should the robot do?","choices":["Continue as if no sensor reading exists","Rewrite the sensor value as 8","Execute the obstacle-response branch","Stop the program before evaluating the condition"],"answer":2,"explanation":""}'::jsonb,'809ecef3d6ff945e45f03f1666f31e4f','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--8',1,'{"question":"What is debugging?","choices":["Adding more hardware without testing","Copying code without understanding it","Choosing a robot''s color scheme","Finding and correcting problems in a program or system"],"answer":3,"explanation":""}'::jsonb,'5c75ea95fc14c1bf5c38c15f200b3126','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--9',1,'{"question":"A program tells a robot to move forward 20 centimeters, but it moves 28 centimeters. Which next step is most useful?","choices":["Measure the difference across repeated trials and adjust the movement command","Change the robot''s name and rerun once","Assume the distance sensor caused the error without checking","Remove all movement commands"],"answer":0,"explanation":""}'::jsonb,'e2d3739fdba917fb2ae583fb626ef95a','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--10',1,'{"question":"In a block-based program, a variable is useful for","choices":["physically connecting a wheel to a motor","storing a value that a program can use or update","detecting light without a sensor","making every instruction run simultaneously"],"answer":1,"explanation":""}'::jsonb,'e5f16357b5a5b0f155026bec92d1f658','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--11',1,'{"question":"A robot repeats a pick-and-place routine until a bin is empty. What condition should end the loop?","choices":["The robot has completed exactly one movement","The battery voltage rises above its starting level","The sensor or counter indicates that no items remain","The program reaches a comment"],"answer":2,"explanation":""}'::jsonb,'ad2f52c37b3fcf800ab1f9f00b168b27','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--12',1,'{"question":"A team''s robot works in a test area but not on a darker floor. What is the best troubleshooting approach?","choices":["Replace the drive motors before examining the sensor","Change the program, floor, and lighting at the same time","Remove the floor sensor data from the report","Investigate how surface color affects the sensor readings and retest controlled changes"],"answer":3,"explanation":""}'::jsonb,'c494b8d3089d3279d97fde7dd3f78d77','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--13',1,'{"question":"Which statement correctly describes input and output in a simple robot system?","choices":["A sensor provides input; a motor can produce output","A motor provides input; an algorithm is a physical output","A battery is an algorithm; a sensor is a chassis","A wheel is a sensor; a program is an actuator"],"answer":0,"explanation":""}'::jsonb,'f12264063c21706a4fb4885dfdc86536','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--14',1,'{"question":"A program contains the command ''turn 90 degrees'' twice in different places. What is one benefit of making this a reusable function?","choices":["It guarantees the robot''s angle sensor is accurate","It can reduce repeated code and make changes easier to manage","It removes the need to test either turn","It changes a conditional into a physical sensor"],"answer":1,"explanation":""}'::jsonb,'49c82259fed3be97887852289deac146','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--15',1,'{"question":"A team wants a robot to stop before crossing a table edge. Which setup best supports that goal?","choices":["Use a sound output and a loop that ignores sensor input","Use a wheel encoder alone to identify every table edge","Use a downward-facing sensor and a tested condition that stops motion when an edge is detected","Use a light actuator to estimate distance"],"answer":2,"explanation":""}'::jsonb,'ea7f147d479543edabae313a973d40ea','official',NULL,NULL,'Coding and Robotics Basics'),
('original:science--engineering-stem--coding-and-robotics-basics:science--engineering-stem--coding-and-robotics-basics--16',1,'{"question":"Why should code be tested with more than one input or situation?","choices":["One successful run proves the program handles every condition","Multiple cases make the algorithm harder to understand","Testing can replace defining the intended behavior","Different cases can reveal errors hidden by a single successful run"],"answer":3,"explanation":""}'::jsonb,'cf5ac5851243e6435ab02459651daba3','official',NULL,NULL,'Coding and Robotics Basics')
